import { buildAnimalCellProcedural } from "./content/animal-cell.procedural";
import { buildBacteriaProcedural } from "./content/bacteria.procedural";
import { buildEpithelialCellProcedural } from "./content/epithelial-cell.procedural";
import { buildHumanBrainCutoutProcedural } from "./content/human-brain-cutout.procedural";
import { buildHumanBrainProcedural } from "./content/human-brain.procedural";
import { buildMuscleCellProcedural } from "./content/muscle-cell.procedural";
import { buildNeuronProcedural } from "./content/neuron.procedural";
import { buildParameciumProcedural } from "./content/paramecium.procedural";
import { buildPlantCellProcedural } from "./content/plant-cell.procedural";
import { buildRedBloodCellProcedural } from "./content/red-blood-cell.procedural";
import { buildWhiteBloodCellProcedural } from "./content/white-blood-cell.procedural";
import { buildYeastCellProcedural } from "./content/yeast-cell.procedural";
import type { AssetRecord, ProceduralSpec } from "./schema";

const PROCEDURAL_BUILDERS: Record<string, () => ProceduralSpec> = {
  "asset-plant-cell": buildPlantCellProcedural,
  "asset-white-blood-cell": buildWhiteBloodCellProcedural,
  "asset-neuron": buildNeuronProcedural,
  "asset-epithelial-cell": buildEpithelialCellProcedural,
  "asset-bacteria": buildBacteriaProcedural,
  "asset-animal-cell": buildAnimalCellProcedural,
  "asset-muscle-cell": buildMuscleCellProcedural,
  "asset-red-blood-cell": buildRedBloodCellProcedural,
  "asset-yeast-cell": buildYeastCellProcedural,
  "asset-paramecium": buildParameciumProcedural,
  "asset-human-brain": buildHumanBrainProcedural,
  "asset-human-brain-cutout": buildHumanBrainCutoutProcedural,
};

const specCache = new Map<string, ProceduralSpec>();
const hydratedAssets = new WeakMap<AssetRecord, AssetRecord>();

export function getProceduralSpec(assetId: string): ProceduralSpec | undefined {
  const cached = specCache.get(assetId);
  if (cached) return cached;
  const build = PROCEDURAL_BUILDERS[assetId];
  if (!build) return undefined;
  const spec = build();
  specCache.set(assetId, spec);
  return spec;
}

export function hydrateAsset(asset: AssetRecord): AssetRecord {
  if (asset.kind !== "procedural" || asset.procedural) return asset;
  const cached = hydratedAssets.get(asset);
  if (cached) return cached;
  const procedural = getProceduralSpec(asset.id);
  if (!procedural) {
    throw new Error(`Missing procedural spec for asset ${asset.id}`);
  }
  const hydrated: AssetRecord = { ...asset, procedural };
  hydratedAssets.set(asset, hydrated);
  return hydrated;
}
