import { createStore, type StoreApi } from "zustand/vanilla";
import type { ViewMode, ViewerUnavailableReason } from "@cas/viewer-core";

export type SceneStatus = "idle" | "loading" | "ready" | "error" | "unavailable";

export type SceneError = {
  code: ViewerUnavailableReason;
  message: string;
  retryable: boolean;
};

export type SceneState = {
  specimenId: string | null;
  focusedStructureId: string | null;
  view: ViewMode;
  cutaway: boolean;
  autoRotate: boolean;
  resetNonce: number;
  status: SceneStatus;
  progress: number;
  meshCount: number;
  error: SceneError | null;
  announcement: string;

  beginSpecimen: (specimenId: string) => void;
  setProgress: (progress: number) => void;
  markReady: (meshCount: number) => void;
  fail: (error: SceneError) => void;
  markUnavailable: (reason: ViewerUnavailableReason, message: string) => void;
  setFocusedStructure: (structureId: string | null) => void;
  setView: (view: ViewMode) => void;
  setCutaway: (enabled: boolean) => void;
  setAutoRotate: (enabled: boolean) => void;
  requestCameraReset: () => void;
};

export type SceneStore = StoreApi<SceneState>;

export type SceneStoreOptions = {
  specimenId?: string | null;
  view?: ViewMode;
  autoRotate?: boolean;
  cutaway?: boolean;
};

export function createSceneStore(options: SceneStoreOptions = {}): SceneStore {
  return createStore<SceneState>()((set, get) => ({
    specimenId: options.specimenId ?? null,
    focusedStructureId: null,
    view: options.view ?? "mesh",
    cutaway: options.cutaway ?? false,
    autoRotate: options.autoRotate ?? false,
    resetNonce: 0,
    status: "idle",
    progress: 0,
    meshCount: 0,
    error: null,
    announcement: "",

    beginSpecimen: (specimenId) => {
      const state = get();
      const sameSpecimen = state.specimenId === specimenId;
      if (sameSpecimen && state.status === "loading") return;
      set({
        specimenId,
        focusedStructureId: sameSpecimen ? state.focusedStructureId : null,
        status: "loading",
        progress: 0,
        meshCount: 0,
        error: null,
      });
    },
    setProgress: (progress) => {
      const clamped = Math.max(0, Math.min(1, progress));
      const status = get().status;
      if (get().progress === clamped && status === "loading") return;
      set({
        progress: clamped,
        status:
          status === "error" || status === "idle" || status === "unavailable" ? "loading" : status,
      });
    },
    markReady: (meshCount) => {
      const specimenId = get().specimenId;
      set({
        status: "ready",
        progress: 1,
        meshCount,
        error: null,
        announcement: specimenId ? `3D model ready for ${specimenId}.` : "3D model ready.",
      });
    },
    fail: (error) => {
      set({
        status: "error",
        error,
        announcement: error.retryable
          ? "The 3D model could not be loaded. A retry is available."
          : "The 3D model is unavailable for this specimen.",
      });
    },
    markUnavailable: (reason, message) => {
      set({
        status: "unavailable",
        error: { code: reason, message, retryable: false },
        announcement: "3D viewing is unavailable. Text and structure information remain available.",
      });
    },
    setFocusedStructure: (structureId) => {
      if (get().focusedStructureId === structureId) return;
      set({ focusedStructureId: structureId });
    },
    setView: (view) => {
      if (get().view === view) return;
      set({
        view,
        announcement:
          view === "focus"
            ? "Focus view. Only the selected structure is emphasised."
            : "Mesh view. All structures are shown.",
      });
    },
    setCutaway: (enabled) => {
      if (get().cutaway === enabled) return;
      set({
        cutaway: enabled,
        announcement: enabled ? "Cutaway on. Outer layers hidden." : "Cutaway off.",
      });
    },
    setAutoRotate: (enabled) => {
      if (get().autoRotate === enabled) return;
      set({ autoRotate: enabled });
    },
    requestCameraReset: () => {
      set({ resetNonce: get().resetNonce + 1 });
    },
  }));
}
