import { mat, part } from "../authoring";
import { computeBrainLobeFrame, type BrainLobeRegion } from "../brain-math";
import type { MaterialSpec, PartSpec, ProceduralShape, ProceduralSpec } from "../schema";

export function buildHumanBrainProcedural(): ProceduralSpec {
  const LOBE_SHAPES: Record<BrainLobeRegion, ProceduralShape> = {
    frontal: "brainFrontalLobe",
    motor: "brainMotorCortex",
    sensory: "brainSensoryCortex",
    parietal: "brainParietalLobe",
    temporal: "brainTemporalLobe",
    occipital: "brainOccipitalLobe",
  };

  const LOBE_MATS: Record<BrainLobeRegion, MaterialSpec> = {
    frontal: mat("#d9877a", {
      roughness: 0.44,
      clearcoat: 0.28,
      emissive: "#5e2820",
      emissiveIntensity: 0.08,
    }),
    motor: mat("#e2b666", {
      roughness: 0.42,
      clearcoat: 0.3,
      emissive: "#694c16",
      emissiveIntensity: 0.1,
    }),
    sensory: mat("#78b4d8", {
      roughness: 0.42,
      clearcoat: 0.3,
      emissive: "#1f4e6b",
      emissiveIntensity: 0.1,
    }),
    parietal: mat("#829acc", {
      roughness: 0.44,
      clearcoat: 0.28,
      emissive: "#243763",
      emissiveIntensity: 0.08,
    }),
    temporal: mat("#6ea895", {
      roughness: 0.44,
      clearcoat: 0.28,
      emissive: "#1c4d3e",
      emissiveIntensity: 0.08,
    }),
    occipital: mat("#9e89c4", {
      roughness: 0.44,
      clearcoat: 0.28,
      emissive: "#3a295e",
      emissiveIntensity: 0.08,
    }),
  };

  const LOBE_SEGMENTS = 36;

  function lobePair(region: BrainLobeRegion, structureId: string): PartSpec[] {
    const frame = computeBrainLobeFrame(region, LOBE_SEGMENTS);
    const shape = LOBE_SHAPES[region];
    const material = LOBE_MATS[region];
    return [
      part({
        id: `${region}-lobe-right`,
        shape,
        position: frame.position,
        scale: frame.scale,
        material,
        structureId,
        cutawayHide: true,
        segments: LOBE_SEGMENTS,
      }),
      part({
        id: `${region}-lobe-left`,
        shape,
        position: [frame.position[0], frame.position[1], -frame.position[2]],
        scale: frame.scale,
        material,
        structureId,
        mirrorZ: true,
        segments: LOBE_SEGMENTS,
      }),
    ];
  }

  const CEREBELLUM_MAT = mat("#b98867", {
    roughness: 0.48,
    clearcoat: 0.22,
    emissive: "#4f311b",
    emissiveIntensity: 0.09,
  });

  const BRAINSTEM_MAT = mat("#d4c2ad", {
    roughness: 0.45,
    clearcoat: 0.24,
    emissive: "#574a39",
    emissiveIntensity: 0.08,
  });

  const CALLOSUM_MAT = mat("#f5ebd6", {
    roughness: 0.4,
    clearcoat: 0.28,
    emissive: "#6b5d47",
    emissiveIntensity: 0.1,
  });

  const THALAMUS_MAT = mat("#b47cc9", {
    roughness: 0.4,
    clearcoat: 0.34,
    emissive: "#492459",
    emissiveIntensity: 0.12,
  });

  const HIPPOCAMPUS_MAT = mat("#e8b254", {
    roughness: 0.38,
    clearcoat: 0.36,
    emissive: "#69450d",
    emissiveIntensity: 0.14,
  });

  const AMYGDALA_MAT = mat("#d95574", {
    roughness: 0.36,
    clearcoat: 0.4,
    emissive: "#69192c",
    emissiveIntensity: 0.16,
  });

  const FORNIX_MAT = mat("#e3c18a", {
    roughness: 0.42,
    clearcoat: 0.3,
    emissive: "#5c4835",
    emissiveIntensity: 0.1,
  });

  return {
    units: "schematic",
    canonicalDiameter: 2,
    notes:
      "Schematic intact 3D human brain modelled after interactive whole-brain anatomy atlases. Bilateral cerebral hemispheres partition cleanly along anatomical sulcal landmarks into frontal, primary motor, primary somatosensory, parietal, temporal, and occipital regions with folded gyri and sulci, sitting above a striated cerebellum and sculpted brainstem. Enabling cutaway hides the right-hemisphere cortex to expose the midline corpus callosum and internal limbic core.",
    parts: [
      ...lobePair("frontal", "frontal-lobe"),
      ...lobePair("motor", "motor-cortex"),
      ...lobePair("sensory", "somatosensory-cortex"),
      ...lobePair("parietal", "parietal-lobe"),
      ...lobePair("temporal", "temporal-lobe"),
      ...lobePair("occipital", "occipital-lobe"),
      part({
        id: "cerebellum-right",
        shape: "cerebellumLobe",
        position: [-0.43, -0.32, 0.18],
        scale: [0.5, 0.38, 0.35],
        material: CEREBELLUM_MAT,
        structureId: "cerebellum",
        segments: 34,
      }),
      part({
        id: "cerebellum-left",
        shape: "cerebellumLobe",
        position: [-0.43, -0.32, -0.18],
        scale: [0.5, 0.38, 0.35],
        material: CEREBELLUM_MAT,
        structureId: "cerebellum",
        mirrorZ: true,
        segments: 34,
      }),
      part({
        id: "cerebellum-vermis",
        shape: "organicBlob",
        position: [-0.43, -0.32, 0],
        scale: [0.3, 0.28, 0.13],
        material: CEREBELLUM_MAT,
        structureId: "cerebellum",
        segments: 20,
      }),
      part({
        id: "brainstem",
        shape: "brainstemCore",
        position: [-0.08, -0.42, 0],
        scale: [0.31, 0.72, 0.27],
        material: BRAINSTEM_MAT,
        structureId: "brainstem",
        segments: 32,
      }),
      part({
        id: "corpus-callosum",
        shape: "corpusCallosum",
        position: [0.04, 0.11, 0],
        scale: [0.62, 0.24, 0.28],
        material: CALLOSUM_MAT,
        structureId: "corpus-callosum",
        segments: 36,
      }),
      part({
        id: "thalamus-right",
        shape: "organicBlob",
        position: [-0.03, 0.0, 0.08],
        scale: [0.24, 0.16, 0.13],
        material: THALAMUS_MAT,
        structureId: "limbic-core",
        segments: 22,
      }),
      part({
        id: "thalamus-left",
        shape: "organicBlob",
        position: [-0.03, 0.0, -0.08],
        scale: [0.24, 0.16, 0.13],
        material: THALAMUS_MAT,
        structureId: "limbic-core",
        mirrorZ: true,
        segments: 22,
      }),
      part({
        id: "hippocampus-right",
        shape: "hippocampusArch",
        position: [-0.06, -0.09, 0.125],
        scale: [0.34, 0.21, 0.12],
        material: HIPPOCAMPUS_MAT,
        structureId: "limbic-core",
        segments: 32,
      }),
      part({
        id: "hippocampus-left",
        shape: "hippocampusArch",
        position: [-0.06, -0.09, -0.125],
        scale: [0.34, 0.21, 0.12],
        material: HIPPOCAMPUS_MAT,
        structureId: "limbic-core",
        mirrorZ: true,
        segments: 32,
      }),
      part({
        id: "amygdala-right",
        shape: "organicBlob",
        position: [0.1, -0.13, 0.13],
        scale: [0.085, 0.075, 0.07],
        material: AMYGDALA_MAT,
        structureId: "limbic-core",
        segments: 18,
      }),
      part({
        id: "amygdala-left",
        shape: "organicBlob",
        position: [0.1, -0.13, -0.13],
        scale: [0.085, 0.075, 0.07],
        material: AMYGDALA_MAT,
        structureId: "limbic-core",
        mirrorZ: true,
        segments: 18,
      }),
      part({
        id: "fornix-right",
        shape: "limbicArch",
        position: [0.01, 0.02, 0.045],
        rotation: [0, 0, -0.1],
        scale: [0.4, 0.24, 0.055],
        material: FORNIX_MAT,
        structureId: "limbic-core",
        segments: 28,
      }),
      part({
        id: "fornix-left",
        shape: "limbicArch",
        position: [0.01, 0.02, -0.045],
        rotation: [0, 0, -0.1],
        scale: [0.4, 0.24, 0.055],
        material: FORNIX_MAT,
        structureId: "limbic-core",
        mirrorZ: true,
        segments: 28,
      }),
    ],
  };
}

export const humanBrainProcedural: ProceduralSpec = /*#__PURE__*/ buildHumanBrainProcedural();
