import { z } from "zod";
import { COMPARE_TRAIT_IDS, TRAIT_LABELS } from "./traits";

/**
 * Authoring schemas for the content registry. These are the single runtime
 * boundary for authored JSON/TS content: nothing downstream should trust a
 * specimen, structure, or asset record that has not passed through Zod.
 */

export const HEX_COLOR = /^#[0-9a-fA-F]{6}$/;

const hexColor = z.string().regex(HEX_COLOR, "Expected a 6-digit hex colour");

export const REVIEW_STATUSES = ["approved", "draft", "blocked"] as const;
export const ReviewStatusSchema = z.enum(REVIEW_STATUSES);
export type ReviewStatus = z.infer<typeof ReviewStatusSchema>;

export const ReviewSchema = z.object({
  status: ReviewStatusSchema,
  reviewer: z.string().min(2),
  reviewedAt: z.string().min(10).nullable(),
  notes: z.string().min(1),
});
export type Review = z.infer<typeof ReviewSchema>;

export const SourceSchema = z.object({
  id: z.string().min(2),
  title: z.string().min(2),
  publisher: z.string().min(2),
  url: z.url(),
  edition: z.string().min(1),
  accessedAt: z.string().min(10),
});
export type Source = z.infer<typeof SourceSchema>;

export const TutorFactSchema = z.object({
  id: z.string().min(2),
  statement: z.string().min(12),
  sourceId: z.string().min(2),
  /** Human-readable locator: chapter/section/table, not a fragile page number alone. */
  locator: z.string().min(2),
  highImpact: z.boolean().default(false),
  /** A recorded second review is required for high-impact claims before release. */
  secondReview: ReviewSchema.nullable().default(null),
});
export type TutorFact = z.infer<typeof TutorFactSchema>;

export const LICENSE_RIGHTS = ["allowed", "not-allowed", "unknown"] as const;

export const LicenseSchema = z.object({
  id: z.string().min(2),
  name: z.string().min(2),
  url: z.url(),
  redistribution: z.enum(LICENSE_RIGHTS),
  modification: z.enum(LICENSE_RIGHTS),
  commercialUse: z.enum(LICENSE_RIGHTS),
  attributionRequired: z.boolean(),
  attributionText: z.string().min(2),
});
export type License = z.infer<typeof LicenseSchema>;

export const LicenseEvidenceSchema = z.object({
  kind: z.enum(["in-repo-authoring", "url", "document", "permission"]),
  locator: z.string().min(2),
  retrievedAt: z.string().min(10),
  notes: z.string().min(8),
});
export type LicenseEvidence = z.infer<typeof LicenseEvidenceSchema>;

export const STRUCTURE_MAPPING_KINDS = ["mesh-mapping", "segmentation-mask", "none"] as const;

export const StructureMappingSchema = z.object({
  kind: z.enum(STRUCTURE_MAPPING_KINDS),
  /** Part IDs from the procedural spec (repeats inherit their parent part ID). */
  meshNames: z.array(z.string().min(2)).default([]),
  evidence: z.string().min(4),
  confidence: z.enum(["high", "medium", "low"]),
  note: z.string().min(4),
});
export type StructureMapping = z.infer<typeof StructureMappingSchema>;

export const StructureSchema = z.object({
  id: z.string().min(2),
  name: z.string().min(2),
  shortName: z.string().min(2).optional(),
  summary: z.string().min(20),
  function: z.string().min(20),
  facts: z.array(TutorFactSchema).min(1),
  mapping: StructureMappingSchema,
  /** Optional plain-language caveat about how the schematic abstracts this structure. */
  schematicNote: z.string().optional(),
});
export type Structure = z.infer<typeof StructureSchema>;

export { COMPARE_TRAIT_IDS, TRAIT_LABELS };
export const CompareTraitIdSchema = z.enum(COMPARE_TRAIT_IDS);
export type CompareTraitId = z.infer<typeof CompareTraitIdSchema>;

export const TraitSchema = z.object({
  id: CompareTraitIdSchema,
  value: z.string().min(1),
  note: z.string().optional(),
});
export type Trait = z.infer<typeof TraitSchema>;

export const SPECIMEN_DOMAINS = ["plant", "animal", "bacteria", "fungi", "protist"] as const;
export const SpecimenDomainSchema = z.enum(SPECIMEN_DOMAINS);
export type SpecimenDomain = z.infer<typeof SpecimenDomainSchema>;

export const PROCEDURAL_SHAPES = [
  "sphere",
  "box",
  "cylinder",
  "capsule",
  "cone",
  "torus",
  "torusKnot",
  "disc",
  "roundedBox",
  "biconcave",
  "curvedSheet",
  "tubeHelix",
  "organicBlob",
  "taperedBranch",
  "brainFrontalLobe",
  "brainMotorCortex",
  "brainSensoryCortex",
  "brainParietalLobe",
  "brainTemporalLobe",
  "brainOccipitalLobe",
  "brainCutoutHemisphere",
  "cerebellumLobe",
  "brainstemCore",
  "corpusCallosum",
  "limbicArch",
  "hippocampusArch",
  "ventricleHorn",
] as const;
export const ProceduralShapeSchema = z.enum(PROCEDURAL_SHAPES);
export type ProceduralShape = z.infer<typeof ProceduralShapeSchema>;

export const REPEAT_PATTERNS = ["scatter", "shell", "ring", "line", "helix", "grid"] as const;

export const Vec3Schema = z.tuple([z.number(), z.number(), z.number()]);
export type Vec3 = z.infer<typeof Vec3Schema>;

export const MaterialSpecSchema = z.object({
  color: hexColor,
  roughness: z.number().min(0).max(1).default(0.55),
  metalness: z.number().min(0).max(1).default(0.03),
  opacity: z.number().min(0).max(1).default(1),
  clearcoat: z.number().min(0).max(1).default(0),
  clearcoatRoughness: z.number().min(0).max(1).default(0.25),
  emissive: hexColor.optional(),
  emissiveIntensity: z.number().min(0).max(2).default(0),
  /** Authored, not inferred: flat shading reads as a diagram rather than a photoreal claim. */
  flatShading: z.boolean().default(false),
});
export type MaterialSpec = z.infer<typeof MaterialSpecSchema>;

export const RepeatSpecSchema = z.object({
  count: z.number().int().min(1).max(400),
  pattern: z.enum(REPEAT_PATTERNS),
  /** Deterministic layout seed. Same seed must always produce the same geometry. */
  seed: z.number().int().min(0).default(1),
  extent: Vec3Schema.default([0.5, 0.5, 0.5]),
  radius: z.number().min(0).max(4).default(0.5),
  turns: z.number().min(0.25).max(12).default(2),
  axis: z.enum(["x", "y", "z"]).default("y"),
  jitter: z.number().min(0).max(1).default(0),
  /** Random Euler jitter applied to each instance, in radians. */
  jitterRotation: z.number().min(0).max(Math.PI).default(0),
});
export type RepeatSpec = z.infer<typeof RepeatSpecSchema>;

export const PartSpecSchema = z.object({
  id: z.string().min(2),
  shape: ProceduralShapeSchema,
  position: Vec3Schema,
  rotation: Vec3Schema.default([0, 0, 0]),
  scale: Vec3Schema,
  material: MaterialSpecSchema,
  /** Registry structure ID. Structural parts must map; decorative parts may omit it. */
  structureId: z.string().min(2).optional(),
  /** Hide this part when the authored cutaway is enabled. */
  cutawayHide: z.boolean().default(false),
  /** Draw authored edge lines (walls, membranes) so translucent shells stay legible. */
  outline: z.boolean().default(false),
  segments: z.number().int().min(6).max(96).default(32),
  /** Mirror local Z coordinates (used for left/right brain hemisphere symmetry). */
  mirrorZ: z.boolean().optional(),
  repeat: RepeatSpecSchema.optional(),
});
export type PartSpec = z.infer<typeof PartSpecSchema>;

export const ProceduralSpecSchema = z.object({
  units: z.literal("schematic"),
  canonicalDiameter: z.number().positive().max(4).default(2),
  parts: z.array(PartSpecSchema).min(1).max(260),
  notes: z.string().min(20),
});
export type ProceduralSpec = z.infer<typeof ProceduralSpecSchema>;

export const AssetCapabilitiesSchema = z.object({
  mesh: z.boolean(),
  focus: z.boolean(),
  cutaway: z.boolean(),
  structureHighlight: z.enum(["mesh-mapping", "none"]),
  screenshot: z.boolean(),
  glbExport: z.boolean(),
});
export type AssetCapabilities = z.infer<typeof AssetCapabilitiesSchema>;

export const GlbAuditSchema = z.object({
  version: z.literal(2),
  totalBytes: z.number().int().positive(),
  extensionsUsed: z.array(z.string()),
  extensionsRequired: z.array(z.string()),
  meshCount: z.number().int().min(0),
  materialCount: z.number().int().min(0),
  textureCount: z.number().int().min(0),
  nodeNames: z.array(z.string()),
  bounds: z
    .object({
      min: Vec3Schema,
      max: Vec3Schema,
    })
    .optional(),
});

export const AssetRecordSchema = z.object({
  id: z.string().min(2),
  kind: z.enum(["procedural", "glb"]),
  /** `procedural://...` for authored geometry, or a same-origin `/assets/...glb` path. */
  uri: z.string().min(2),
  byteSize: z.number().int().nonnegative(),
  license: LicenseSchema,
  licenseEvidence: z.array(LicenseEvidenceSchema).min(1),
  rightsReview: ReviewSchema,
  attribution: z.string().min(2),
  export: z.object({ png: z.boolean(), glb: z.boolean() }),
  capabilities: AssetCapabilitiesSchema,
  procedural: ProceduralSpecSchema.optional(),
  glbAudit: GlbAuditSchema.optional(),
});
export type AssetRecord = z.infer<typeof AssetRecordSchema>;

export const SpecimenSchema = z.object({
  id: z.string().min(2),
  slug: z.string().regex(/^[a-z0-9-]+$/),
  name: z.string().min(2),
  shortName: z.string().min(2),
  cellType: z.string().min(2),
  species: z.string().min(2),
  taxonNote: z.string().min(8),
  domain: SpecimenDomainSchema,
  accent: hexColor,
  summary: z.string().min(20),
  overview: z.string().min(40),
  sizeNote: z.string().min(8),
  scaleNote: z.string().min(20),
  structures: z.array(StructureSchema).min(5),
  traits: z.array(TraitSchema).length(COMPARE_TRAIT_IDS.length),
  assetId: z.string().min(2),
  previewPath: z.string().startsWith("/previews/"),
  capabilities: AssetCapabilitiesSchema,
  contentReview: ReviewSchema,
  contentVersion: z.string().min(1),
  updatedAt: z.string().min(10),
});
export type Specimen = z.infer<typeof SpecimenSchema>;

export const RegistrySchema = z.object({
  version: z.string().min(1),
  specimens: z.array(SpecimenSchema),
  assets: z.array(AssetRecordSchema),
  sources: z.array(SourceSchema),
});
export type Registry = z.infer<typeof RegistrySchema>;
