import { alignZToVector, limbBetween, mat, part, rep } from "../authoring";
import type { ProceduralSpec, Vec3 } from "../schema";

export function buildRedBloodCellProcedural(): ProceduralSpec {
  const SPECTRIN_RING_STEPS = 10;
  const UPPER_RING: Vec3[] = Array.from({ length: SPECTRIN_RING_STEPS }, (_, idx) => {
    const angle = (idx / SPECTRIN_RING_STEPS) * Math.PI * 2;
    return [Math.cos(angle) * 0.6, 0.19, Math.sin(angle) * 0.6];
  });
  const LOWER_RING: Vec3[] = Array.from({ length: SPECTRIN_RING_STEPS }, (_, idx) => {
    const angle = (idx / SPECTRIN_RING_STEPS) * Math.PI * 2;
    return [Math.cos(angle) * 0.6, -0.19, Math.sin(angle) * 0.6];
  });
  const EQUATOR_RING: Vec3[] = Array.from({ length: SPECTRIN_RING_STEPS }, (_, idx) => {
    const angle = ((idx + 0.5) / SPECTRIN_RING_STEPS) * Math.PI * 2;
    return [Math.cos(angle) * 0.85, 0, Math.sin(angle) * 0.85];
  });

  const SPECTRIN_STRUTS: Array<[Vec3, Vec3]> = [];
  for (let i = 0; i < SPECTRIN_RING_STEPS; i += 1) {
    const next = (i + 1) % SPECTRIN_RING_STEPS;
    SPECTRIN_STRUTS.push([UPPER_RING[i]!, UPPER_RING[next]!]);
    SPECTRIN_STRUTS.push([LOWER_RING[i]!, LOWER_RING[next]!]);
    SPECTRIN_STRUTS.push([UPPER_RING[i]!, EQUATOR_RING[i]!]);
    SPECTRIN_STRUTS.push([LOWER_RING[i]!, EQUATOR_RING[i]!]);
    SPECTRIN_STRUTS.push([UPPER_RING[next]!, EQUATOR_RING[i]!]);
    SPECTRIN_STRUTS.push([LOWER_RING[next]!, EQUATOR_RING[i]!]);
  }

  const TRANSPORTER_SITES = Array.from({ length: 8 }, (_, idx) => {
    const angle = (idx / 8) * Math.PI * 2 + 0.2;
    const nx = Math.cos(angle);
    const nz = Math.sin(angle);
    const y = idx % 2 === 0 ? 0.08 : -0.08;
    const r = 0.86;
    return {
      pos: [nx * r, y, nz * r] as Vec3,
      rot: alignZToVector([nx, y * 0.8, nz]),
    };
  });

  const GLYCOCALYX_SITES = Array.from({ length: 14 }, (_, idx) => {
    const angle = (idx / 14) * Math.PI * 2 + 0.12;
    const nx = Math.cos(angle);
    const nz = Math.sin(angle);
    const bandY = idx % 3 === 0 ? 0.25 : idx % 3 === 1 ? -0.25 : 0;
    const baseR = bandY === 0 ? 0.93 : 0.72;
    const tipR = bandY === 0 ? 1.03 : 0.78;
    const tipY = bandY === 0 ? 0 : bandY * 1.24;
    const base: Vec3 = [nx * baseR, bandY, nz * baseR];
    const tip: Vec3 = [nx * tipR, tipY, nz * tipR];
    return { base, tip };
  });

  const SPECTRIN_MAT = mat("#d68ca3", {
    roughness: 0.42,
    clearcoat: 0.3,
    emissive: "#6b293f",
    emissiveIntensity: 0.14,
  });
  const SPECTRIN_NODE_MAT = mat("#f2b8c9", {
    roughness: 0.35,
    emissive: "#853852",
    emissiveIntensity: 0.18,
  });
  const TRANSPORTER_MAT = mat("#7ac4d4", {
    roughness: 0.32,
    clearcoat: 0.5,
    emissive: "#1f5a69",
    emissiveIntensity: 0.18,
  });
  const GLYCO_STALK_MAT = mat("#f0cfd6", { roughness: 0.45, clearcoat: 0.3 });
  const GLYCO_TIP_MAT = mat("#ffebf0", {
    roughness: 0.3,
    emissive: "#945464",
    emissiveIntensity: 0.16,
  });

  return {
    units: "schematic",
    canonicalDiameter: 2,
    notes:
      "Schematic human erythrocyte (biconcave disc). The glossy plasma membrane (with authored cutaway) encloses a triangulated sub-membrane spectrin-actin cytoskeleton, a biconcave hemoglobin-packed cytoplasm, transmembrane Band 3 / aquaporin channel complexes, cytosolic carbonic anhydrase clusters, and outer glycocalyx carbohydrate antennas.",
    parts: [
      part({
        id: "plasma-membrane",
        shape: "biconcave",
        position: [0, 0, 0],
        scale: [1.88, 0.56, 1.88],
        material: mat("#e36d78", {
          opacity: 0.2,
          roughness: 0.2,
          clearcoat: 0.88,
          emissive: "#781c26",
          emissiveIntensity: 0.1,
        }),
        structureId: "plasma-membrane",
        cutawayHide: true,
        outline: true,
        segments: 48,
      }),
      ...SPECTRIN_STRUTS.map(([a, b], idx) => {
        const seg = limbBetween(a, b, 0.012, 2);
        return part({
          id: `spectrin-strut-${idx}`,
          shape: "capsule",
          position: seg.position,
          rotation: seg.rotation,
          scale: seg.scale,
          material: SPECTRIN_MAT,
          structureId: "spectrin-skeleton",
          segments: 8,
        });
      }),
      ...EQUATOR_RING.map((pos, idx) =>
        part({
          id: `spectrin-node-${idx}`,
          shape: "sphere",
          position: pos,
          scale: [0.036, 0.036, 0.036],
          material: SPECTRIN_NODE_MAT,
          structureId: "spectrin-skeleton",
          segments: 12,
        }),
      ),
      part({
        id: "hemoglobin-matrix",
        shape: "biconcave",
        position: [0, 0, 0],
        scale: [1.7, 0.44, 1.7],
        material: mat("#c43343", {
          opacity: 0.34,
          roughness: 0.32,
          clearcoat: 0.5,
          emissive: "#6b111d",
          emissiveIntensity: 0.18,
        }),
        structureId: "hemoglobin",
        segments: 40,
      }),
      part({
        id: "hemoglobin-tetramer-rim",
        shape: "sphere",
        position: [0, 0, 0],
        scale: [0.075, 0.075, 0.075],
        material: mat("#eb4d5e", {
          roughness: 0.35,
          clearcoat: 0.38,
          emissive: "#8a1b28",
          emissiveIntensity: 0.22,
        }),
        structureId: "hemoglobin",
        segments: 14,
        repeat: rep({
          count: 14,
          pattern: "ring",
          axis: "y",
          radius: 0.62,
          seed: 211,
          jitter: 0.25,
        }),
      }),
      part({
        id: "hemoglobin-tetramer-inner",
        shape: "sphere",
        position: [0, 0, 0],
        scale: [0.055, 0.055, 0.055],
        material: mat("#d9384a", {
          roughness: 0.38,
          emissive: "#781420",
          emissiveIntensity: 0.2,
        }),
        structureId: "hemoglobin",
        segments: 12,
        repeat: rep({
          count: 8,
          pattern: "ring",
          axis: "y",
          radius: 0.36,
          seed: 213,
          jitter: 0.18,
        }),
      }),
      ...TRANSPORTER_SITES.map((site, idx) =>
        part({
          id: `membrane-transporter-${idx}`,
          shape: "torus",
          position: site.pos,
          rotation: site.rot,
          scale: [0.08, 0.08, 0.11],
          material: TRANSPORTER_MAT,
          structureId: "membrane-transporters",
          segments: 16,
        }),
      ),
      part({
        id: "carbonic-anhydrase",
        shape: "sphere",
        position: [0, 0.02, 0],
        scale: [0.058, 0.058, 0.058],
        material: mat("#e8bd68", {
          roughness: 0.45,
          flatShading: true,
          emissive: "#855b14",
          emissiveIntensity: 0.2,
        }),
        structureId: "carbonic-anhydrase",
        segments: 10,
        repeat: rep({
          count: 10,
          pattern: "ring",
          axis: "y",
          radius: 0.5,
          seed: 223,
          jitter: 0.35,
        }),
      }),
      ...GLYCOCALYX_SITES.flatMap((site, idx) => {
        const seg = limbBetween(site.base, site.tip, 0.018, 1);
        return [
          part({
            id: `glycocalyx-stalk-${idx}`,
            shape: "taperedBranch",
            position: seg.position,
            rotation: seg.rotation,
            scale: seg.scale,
            material: GLYCO_STALK_MAT,
            structureId: "glycocalyx",
            cutawayHide: true,
            segments: 8,
          }),
          part({
            id: `glycocalyx-sugar-${idx}`,
            shape: "sphere",
            position: site.tip,
            scale: [0.026, 0.026, 0.026],
            material: GLYCO_TIP_MAT,
            structureId: "glycocalyx",
            cutawayHide: true,
            segments: 10,
          }),
        ];
      }),
    ],
  };
}

export const redBloodCellProcedural: ProceduralSpec = /*#__PURE__*/ buildRedBloodCellProcedural();
