import { alignYToVector, alignZToVector, mat, part, rep } from "../authoring";
import type { ProceduralSpec, Vec3 } from "../schema";

export function buildBacteriaProcedural(): ProceduralSpec {
  const PORIN_SITES: Array<{ pos: Vec3; rot: Vec3 }> = [
    { pos: [-0.36, 0.22, 0.04], rot: alignZToVector([0, 1, 0.2]) },
    { pos: [0.18, 0.14, 0.175], rot: alignZToVector([0, 0.6, 0.8]) },
    { pos: [0.44, -0.18, 0.135], rot: alignZToVector([0, -0.8, 0.6]) },
    { pos: [-0.14, -0.205, -0.09], rot: alignZToVector([0, -0.9, -0.4]) },
    { pos: [0.3, 0.17, -0.145], rot: alignZToVector([0, 0.75, -0.65]) },
  ];

  const PILUS_COUNT = 24;
  const PILI_SITES = Array.from({ length: PILUS_COUNT }, (_, idx) => {
    const x = -0.64 + (idx / (PILUS_COUNT - 1)) * 1.28;
    const angle = idx * 2.3999632; // Golden-angle spiral around the rod cylinder.
    const ny = Math.cos(angle);
    const nz = Math.sin(angle);
    const surfaceR = 0.215;
    const len = 0.11 + ((idx * 17) % 5) * 0.012;
    const tiltX = (idx % 2 === 0 ? 1 : -1) * 0.18;
    const dir: Vec3 = [tiltX, ny, nz];
    const center: Vec3 = [
      x + tiltX * (len * 0.45),
      ny * (surfaceR + len * 0.42),
      nz * (surfaceR + len * 0.42),
    ];
    return { pos: center, rot: alignYToVector(dir), len };
  });

  const PILUS_MAT = mat("#c8dec8", {
    roughness: 0.5,
    clearcoat: 0.25,
    emissive: "#405c44",
    emissiveIntensity: 0.08,
  });

  return {
    units: "schematic",
    canonicalDiameter: 2,
    notes:
      "Schematic Gram-negative rod aligned horizontally along X. Three glossy envelope layers (outer membrane with porins, peptidoglycan wall, and plasma membrane) have an authored cutaway enclosing dual supercoiled nucleoid DNA loops, plasmids, cytoplasmically confined 70S ribosomes, basal-body rotor rings with paired continuous helical flagella, and surface-anchored pili.",
    parts: [
      part({
        id: "outer-membrane",
        shape: "capsule",
        position: [0, 0, 0],
        scale: [0.46, 1.0, 0.46],
        material: mat("#a8c9b8", {
          opacity: 0.14,
          roughness: 0.28,
          clearcoat: 0.68,
          emissive: "#2c5c44",
          emissiveIntensity: 0.07,
        }),
        rotation: [0, 0, Math.PI / 2],
        structureId: "outer-membrane",
        cutawayHide: true,
        outline: true,
        segments: 36,
      }),
      ...PORIN_SITES.map((site, idx) =>
        part({
          id: `outer-porin-${idx}`,
          shape: "torus",
          position: site.pos,
          rotation: site.rot,
          scale: [0.05, 0.05, 0.07],
          material: mat("#cce3d6", {
            roughness: 0.35,
            emissive: "#3b6e52",
            emissiveIntensity: 0.12,
          }),
          structureId: "outer-membrane",
          cutawayHide: true,
          segments: 12,
        }),
      ),
      part({
        id: "cell-wall",
        shape: "capsule",
        position: [0, 0, 0],
        scale: [0.42, 0.95, 0.42],
        material: mat("#75b59a", {
          opacity: 0.22,
          roughness: 0.45,
          clearcoat: 0.55,
          emissive: "#1f5c44",
          emissiveIntensity: 0.08,
        }),
        rotation: [0, 0, Math.PI / 2],
        structureId: "cell-wall",
        cutawayHide: true,
        outline: true,
        segments: 32,
      }),
      part({
        id: "plasma-membrane",
        shape: "capsule",
        position: [0, 0, 0],
        scale: [0.38, 0.9, 0.38],
        material: mat("#7cc9d6", {
          opacity: 0.16,
          roughness: 0.28,
          clearcoat: 0.68,
          emissive: "#2c6773",
          emissiveIntensity: 0.07,
        }),
        rotation: [0, 0, Math.PI / 2],
        structureId: "plasma-membrane",
        cutawayHide: true,
        outline: true,
        segments: 32,
      }),
      part({
        id: "nucleoid",
        shape: "torusKnot",
        position: [0.06, 0, 0],
        scale: [0.56, 0.22, 0.22],
        material: mat("#8fe0a4", {
          roughness: 0.45,
          clearcoat: 0.2,
          emissive: "#296e3c",
          emissiveIntensity: 0.18,
        }),
        rotation: [0.35, 0.15, 0.25],
        structureId: "nucleoid",
        segments: 84,
      }),
      part({
        id: "nucleoid-loop-b",
        shape: "torusKnot",
        position: [-0.08, 0.01, -0.01],
        scale: [0.44, 0.18, 0.18],
        material: mat("#a8d99a", { roughness: 0.48, emissive: "#3a782f", emissiveIntensity: 0.14 }),
        rotation: [1.1, 0.4, -0.3],
        structureId: "nucleoid",
        segments: 64,
      }),
      part({
        id: "nucleoid-plasmid-a",
        shape: "torus",
        position: [0.46, 0.06, 0.06],
        rotation: [0.7, 0.3, 0.2],
        scale: [0.075, 0.075, 0.06],
        material: mat("#c4f0a8", { roughness: 0.4, emissive: "#4d8a32", emissiveIntensity: 0.2 }),
        structureId: "nucleoid",
        segments: 20,
      }),
      part({
        id: "nucleoid-plasmid-b",
        shape: "torus",
        position: [-0.42, -0.06, -0.06],
        rotation: [-0.5, 0.8, 0.1],
        scale: [0.065, 0.065, 0.06],
        material: mat("#c4f0a8", { roughness: 0.4, emissive: "#4d8a32", emissiveIntensity: 0.2 }),
        structureId: "nucleoid",
        segments: 20,
      }),
      part({
        id: "ribosome",
        shape: "sphere",
        position: [0, 0, 0],
        scale: [0.024, 0.024, 0.024],
        material: mat("#f5dd9d", { roughness: 0.5, emissive: "#785a18", emissiveIntensity: 0.14 }),
        structureId: "ribosome",
        segments: 8,
        repeat: rep({
          count: 52,
          pattern: "scatter",
          seed: 83,
          extent: [0.64, 0.12, 0.12],
          jitter: 0.25,
        }),
      }),
      part({
        id: "flagellum-filament",
        shape: "tubeHelix",
        position: [-1.42, 0.02, 0],
        scale: [0.82, 0.24, 0.24],
        material: mat("#d6e2e8", {
          roughness: 0.38,
          clearcoat: 0.45,
          emissive: "#526670",
          emissiveIntensity: 0.14,
        }),
        structureId: "flagellum",
        segments: 48,
      }),
      part({
        id: "flagellum-filament-b",
        shape: "tubeHelix",
        position: [-1.44, -0.06, 0.05],
        rotation: [1.8, 0.08, -0.14],
        scale: [0.8, 0.22, 0.22],
        material: mat("#c5d4db", {
          roughness: 0.4,
          clearcoat: 0.4,
          emissive: "#455963",
          emissiveIntensity: 0.12,
        }),
        structureId: "flagellum",
        segments: 44,
      }),
      part({
        id: "flagellum-hook",
        shape: "capsule",
        position: [-1.0, 0, 0],
        rotation: [0, 0, Math.PI / 2],
        scale: [0.032, 0.075, 0.032],
        material: mat("#e3ebf0", { roughness: 0.35, clearcoat: 0.5 }),
        structureId: "flagellum",
        segments: 16,
      }),
      part({
        id: "flagellum-motor-l",
        shape: "torus",
        position: [-0.94, 0, 0],
        rotation: [0, Math.PI / 2, 0],
        scale: [0.095, 0.095, 0.08],
        material: mat("#e8b878", { roughness: 0.4, emissive: "#784d18", emissiveIntensity: 0.18 }),
        structureId: "flagellum",
        segments: 18,
      }),
      part({
        id: "flagellum-motor-ms",
        shape: "torus",
        position: [-0.88, 0, 0],
        rotation: [0, Math.PI / 2, 0],
        scale: [0.115, 0.115, 0.09],
        material: mat("#d69d5a", { roughness: 0.4, emissive: "#6b4214", emissiveIntensity: 0.18 }),
        structureId: "flagellum",
        segments: 18,
      }),
      ...PILI_SITES.map((site, idx) =>
        part({
          id: `pilus-${idx}`,
          shape: "taperedBranch",
          position: site.pos,
          rotation: site.rot,
          scale: [0.018, site.len, 0.018],
          material: PILUS_MAT,
          structureId: "pilus",
          segments: 10,
        }),
      ),
    ],
  };
}

export const bacteriaProcedural: ProceduralSpec = /*#__PURE__*/ buildBacteriaProcedural();
