import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  createSceneStore,
  ViewerHost,
  type ViewerHandle,
  type ViewerReadyInfo,
} from "@cas/viewer-adapter";
import { hydrateAsset } from "@cas/content-registry/procedural";
import type { AssetRecord, Specimen } from "@cas/content-registry";
import { previewUrl } from "../content";
import { useVanillaStore } from "../lib/use-vanilla-store";
import { useSlidingPill } from "../lib/use-sliding-pill";
import { IconCamera, IconClose, IconCutaway, IconReset, IconRotate } from "../components/Icons";

export type ViewerPaneProps = {
  specimen: Specimen;
  asset: AssetRecord;
  selectedStructureId: string | null;
  onSelectStructure: (structureId: string | null) => void;
  reduceMotion: boolean;
  autoRotate: boolean;
  compact?: boolean;
};

type ViewerStats = {
  specimenId: string;
  meshCount: number;
  buildMs: number;
  source: string;
  webgl: string;
};

function download(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * App-side adapter boundary. This module is loaded through React.lazy, so the
 * Three.js graph stays out of the initial route bundle.
 */
export function ViewerPane({
  specimen,
  asset,
  selectedStructureId,
  onSelectStructure,
  reduceMotion,
  autoRotate,
  compact = false,
}: ViewerPaneProps) {
  const [store] = useState(() =>
    createSceneStore({
      specimenId: specimen.id,
      view: "mesh",
      autoRotate,
    }),
  );
  const scene = useVanillaStore(store);
  const handleRef = useRef<ViewerHandle>(null);
  const [stats, setStats] = useState<ViewerStats | null>(null);
  const [screenshotError, setScreenshotError] = useState("");

  useEffect(() => {
    const sceneStore = store.getState();
    sceneStore.setFocusedStructure(selectedStructureId);
    sceneStore.setView(selectedStructureId ? "focus" : "mesh");
  }, [selectedStructureId, specimen.id, store]);

  useEffect(() => {
    store.getState().setAutoRotate(autoRotate);
  }, [autoRotate, store]);

  // Pointer picks inside the canvas travel back through the same selection
  // path as the keyboard-operable structure list. Read the live store value:
  // the render snapshot can be one command behind, and treating that stale
  // value as a pick makes the two-way selection sync oscillate.
  useEffect(() => {
    const focused = store.getState().focusedStructureId;
    if (focused === selectedStructureId) return;
    onSelectStructure(focused);
  }, [scene.focusedStructureId, selectedStructureId, onSelectStructure, store]);

  const currentStats = stats?.specimenId === specimen.id ? stats : null;
  const hydratedAsset = useMemo(() => hydrateAsset(asset), [asset]);
  const ready = scene.status === "ready";
  const handleViewerReady = useCallback((info: ViewerReadyInfo) => {
    setStats({
      specimenId: info.specimenId,
      meshCount: info.meshCount,
      buildMs: info.buildMs,
      source: info.source,
      webgl: info.webgl,
    });
    setScreenshotError("");
  }, []);
  const showPreview = !ready;
  const viewPill = useSlidingPill<HTMLButtonElement>(scene.view === "focus" ? 1 : 0, reduceMotion);

  async function takeScreenshot() {
    setScreenshotError("");
    try {
      const blob = await handleRef.current?.screenshot();
      if (!blob) throw new Error("The viewer did not return an image");
      download(blob, `${specimen.slug}-${new Date().toISOString().slice(0, 10)}.png`);
    } catch (cause) {
      setScreenshotError(
        cause instanceof Error ? cause.message : "The screenshot could not be saved.",
      );
    }
  }

  function retry() {
    store.getState().beginSpecimen(specimen.id);
    handleRef.current?.reload();
  }

  return (
    <section
      className={`viewer-pane${compact ? " viewer-pane--compact" : ""}`}
      aria-label={`${specimen.name} 3D viewer`}
      data-viewer-state={scene.status}
    >
      <div className="viewer-pane__stage-wrap">
        <div className="viewer-pane__stage">
          {showPreview && (
            <img
              className="viewer-pane__preview"
              src={previewUrl(specimen.previewPath)}
              alt={`${specimen.name} schematic preview. ${specimen.summary}`}
              width={640}
              height={640}
              loading="eager"
              decoding="async"
            />
          )}
          <ViewerHost
            ref={handleRef}
            specimen={specimen}
            asset={hydratedAsset}
            store={store}
            reduceMotion={reduceMotion}
            className="viewer-pane__host"
            onReady={handleViewerReady}
          />

          <div className="viewer-pane__badges">
            <span className="badge badge--schematic">Schematic · not to scale</span>
            {selectedStructureId && (
              <span className="badge">
                {scene.view === "focus" ? "Structure focus" : "Mesh view"}
              </span>
            )}
          </div>

          {scene.status === "loading" && (
            <div className="viewer-pane__overlay" role="status" aria-live="polite">
              <span className="spinner" aria-hidden="true" />
              <p>
                Building {specimen.name}
                {scene.progress > 0 && scene.progress < 1
                  ? ` — ${Math.round(scene.progress * 100)}%`
                  : "…"}
              </p>
              <div className="progress" aria-hidden="true">
                <span style={{ width: `${Math.max(6, Math.round(scene.progress * 100))}%` }} />
              </div>
            </div>
          )}

          {(scene.status === "error" || scene.status === "unavailable") && (
            <div
              className="viewer-pane__overlay viewer-pane__overlay--error"
              role="group"
              aria-label="3D unavailable"
            >
              <p className="eyebrow">
                {scene.status === "unavailable" ? "3D unavailable" : "Viewer error"}
              </p>
              <p>{scene.error?.message ?? "The 3D view could not start."}</p>
              <p className="muted">
                The preview and the full structure list below stay available. Every fact can be read
                without graphics.
              </p>
              {scene.status === "error" && scene.error?.retryable && (
                <button type="button" className="button button--primary" onClick={retry}>
                  Retry 3D view
                </button>
              )}
            </div>
          )}
        </div>

        <div
          className="viewer-pane__toolbar"
          role="group"
          aria-label={`${specimen.name} view controls`}
        >
          <div
            className="segmented"
            role="group"
            aria-label="View mode"
            ref={viewPill.containerRef}
          >
            <span className="spring-pill" aria-hidden="true" ref={viewPill.pillRef} />
            <button
              ref={viewPill.registerItem(0)}
              type="button"
              aria-pressed={scene.view === "mesh"}
              disabled={!ready}
              onClick={() => store.getState().setView("mesh")}
            >
              Mesh
            </button>
            <button
              ref={viewPill.registerItem(1)}
              type="button"
              aria-pressed={scene.view === "focus"}
              disabled={!ready || !selectedStructureId}
              onClick={() => store.getState().setView("focus")}
            >
              Focus
            </button>
          </div>

          {asset.capabilities.cutaway && (
            <button
              type="button"
              className="button button--ghost"
              aria-pressed={scene.cutaway}
              disabled={!ready}
              onClick={() => store.getState().setCutaway(!scene.cutaway)}
            >
              <IconCutaway />
              <span>Cutaway</span>
            </button>
          )}

          <button
            type="button"
            className="button button--ghost"
            aria-pressed={scene.autoRotate}
            disabled={!ready}
            onClick={() => store.getState().setAutoRotate(!scene.autoRotate)}
          >
            <IconRotate />
            <span>Auto-rotate</span>
          </button>

          <button
            type="button"
            className="button button--ghost"
            disabled={!ready}
            onClick={() => store.getState().requestCameraReset()}
          >
            <IconReset />
            <span>Reset view</span>
          </button>

          {asset.export.png && (
            <button
              type="button"
              className="button button--ghost"
              disabled={!ready}
              onClick={() => void takeScreenshot()}
            >
              <IconCamera />
              <span>Save PNG</span>
            </button>
          )}

          {selectedStructureId && (
            <button
              type="button"
              className="button button--ghost viewer-pane__clear"
              onClick={() => onSelectStructure(null)}
            >
              <IconClose />
              <span>Clear selection</span>
            </button>
          )}
        </div>
      </div>

      <div className="viewer-pane__status">
        <p className="muted small" role="status" aria-live="polite">
          {scene.announcement ||
            (ready
              ? `${specimen.name} is ready. ${currentStats?.meshCount ?? 0} schematic meshes.`
              : "Preparing the 3D view.")}
        </p>
        <p className="muted small">
          {currentStats
            ? `${currentStats.meshCount} meshes · ${currentStats.buildMs} ms build · ${currentStats.webgl}`
            : scene.status === "loading"
              ? "Loading only the viewer chunk"
              : "Preview is a static SVG"}
        </p>
      </div>

      {screenshotError && (
        <p className="form-error" role="alert">
          {screenshotError}
        </p>
      )}
    </section>
  );
}

export default ViewerPane;
