export type ViewerCapability = {
  supported: boolean;
  api: "webgl2" | "webgl1" | null;
  reason: string | null;
  maxTextureSize: number | null;
  renderer: string | null;
};

const capabilityCache = new WeakMap<Document, ViewerCapability>();

function unavailable(reason: string): ViewerCapability {
  return {
    supported: false,
    api: null,
    reason,
    maxTextureSize: null,
    renderer: null,
  };
}

function probeDocument(targetDocument: Document): ViewerCapability {
  let canvas: HTMLCanvasElement;
  try {
    canvas = targetDocument.createElement("canvas");
  } catch {
    return unavailable("Could not create a canvas element");
  }

  for (const api of ["webgl2", "webgl1"] as const) {
    let gl: WebGLRenderingContext | WebGL2RenderingContext | null = null;
    try {
      gl = canvas.getContext(api === "webgl2" ? "webgl2" : "webgl", {
        failIfMajorPerformanceCaveat: false,
      }) as WebGLRenderingContext | WebGL2RenderingContext | null;
    } catch {
      gl = null;
    }
    if (!gl) continue;

    let renderer: string | null = null;
    try {
      const debug = gl.getExtension("WEBGL_debug_renderer_info");
      if (debug) renderer = String(gl.getParameter(debug.UNMASKED_RENDERER_WEBGL));
    } catch {
      renderer = null;
    }

    let maxTextureSize: number | null = null;
    try {
      maxTextureSize = gl.getParameter(gl.MAX_TEXTURE_SIZE) as number;
    } catch {
      maxTextureSize = null;
    }

    try {
      gl.getExtension("WEBGL_lose_context")?.loseContext();
    } catch {
      // The browser will reclaim the probe context.
    }

    return { supported: true, api, reason: null, maxTextureSize, renderer };
  }

  return unavailable(
    "WebGL is unavailable or disabled in this browser. Text, preview, and the structure list remain usable.",
  );
}

/**
 * Lightweight WebGL probe with no Three.js dependency, so the app shell can
 * decide whether to fetch the viewer chunk at all. Returns a reason rather than
 * throwing or logging when graphics are unavailable.
 */
export function detectViewerCapability(doc?: Document): ViewerCapability {
  if (typeof document === "undefined" && !doc) {
    return unavailable("No DOM available in this environment");
  }

  const targetDocument = doc ?? document;
  const cached = capabilityCache.get(targetDocument);
  if (cached) return cached;

  const result = probeDocument(targetDocument);
  capabilityCache.set(targetDocument, result);
  return result;
}
