import type {
  MaterialSpec,
  PartSpec,
  ProceduralShape,
  ProceduralSpec,
  RepeatSpec,
  Vec3,
} from "./schema";

/**
 * Pure procedural-geometry expansion. Content is authored as schematic parts;
 * viewer-core turns these instances into Three.js meshes while the asset
 * pipeline uses the same functions for bounds/normalisation reports.
 *
 * No randomness is unseeded: the same registry entry always produces the same
 * geometry on every device, which keeps render smoke tests and previews stable.
 */

export type ProceduralInstance = {
  key: string;
  partId: string;
  structureId?: string;
  shape: ProceduralShape;
  position: Vec3;
  rotation: Vec3;
  scale: Vec3;
  material: MaterialSpec;
  cutawayHide: boolean;
  outline: boolean;
  segments: number;
  mirrorZ?: boolean;
  repeatIndex?: number;
};

export type Bounds = { min: Vec3; max: Vec3 };

export type Normalization = {
  scale: number;
  translation: Vec3;
  sourceBounds: Bounds;
  normalizedBounds: Bounds;
  canonicalDiameter: number;
};

/** Mulberry32 — tiny, fast, deterministic. */
export function createRng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Unit extents of each primitive before per-instance scale is applied. */
export const SHAPE_EXTENTS: Record<ProceduralShape, Vec3> = {
  sphere: [1, 1, 1],
  box: [1, 1, 1],
  cylinder: [1, 1, 1],
  capsule: [1, 2, 1],
  cone: [1, 1, 1],
  torus: [1, 1, 0.3],
  torusKnot: [1.2, 1.2, 1.2],
  disc: [1, 0.12, 1],
  roundedBox: [1, 1, 1],
  biconcave: [1, 1, 1],
  curvedSheet: [1, 0.4, 1],
  tubeHelix: [1, 0.4, 0.4],
  organicBlob: [1, 1, 1],
  taperedBranch: [1, 1, 1],
  brainFrontalLobe: [1, 1, 1],
  brainMotorCortex: [1, 1, 1],
  brainSensoryCortex: [1, 1, 1],
  brainParietalLobe: [1, 1, 1],
  brainTemporalLobe: [1, 1, 1],
  brainOccipitalLobe: [1, 1, 1],
  brainCutoutHemisphere: [1, 1, 1],
  cerebellumLobe: [1, 1, 1],
  brainstemCore: [1, 1, 1],
  corpusCallosum: [1, 1, 1],
  limbicArch: [1, 1, 1],
  hippocampusArch: [1, 1, 1],
  ventricleHorn: [1, 1, 1],
};

function repeatOffset(repeat: RepeatSpec, index: number, rng: () => number): Vec3 {
  const [ex, ey, ez] = repeat.extent;
  const count = repeat.count;
  const t = count === 1 ? 0.5 : index / count;
  switch (repeat.pattern) {
    case "scatter": {
      const z = rng() * 2 - 1;
      const theta = rng() * Math.PI * 2;
      const r = Math.cbrt(rng());
      const s = Math.sqrt(Math.max(0, 1 - z * z));
      return [Math.cos(theta) * s * r * ex, z * r * ey, Math.sin(theta) * s * r * ez];
    }
    case "shell": {
      const z = rng() * 2 - 1;
      const theta = rng() * Math.PI * 2;
      const s = Math.sqrt(Math.max(0, 1 - z * z));
      return [Math.cos(theta) * s * ex, z * ey, Math.sin(theta) * s * ez];
    }
    case "ring": {
      const angle = t * Math.PI * 2;
      const c = Math.cos(angle) * repeat.radius;
      const s = Math.sin(angle) * repeat.radius;
      if (repeat.axis === "x") return [0, c, s];
      if (repeat.axis === "z") return [c, s, 0];
      return [c, 0, s];
    }
    case "line": {
      const span = (t * 2 - 1) * (repeat.axis === "x" ? ex : repeat.axis === "y" ? ey : ez);
      return repeat.axis === "x" ? [span, 0, 0] : repeat.axis === "y" ? [0, span, 0] : [0, 0, span];
    }
    case "helix": {
      const span = (t * 2 - 1) * (repeat.axis === "x" ? ex : repeat.axis === "y" ? ey : ez);
      const angle = t * Math.PI * 2 * repeat.turns;
      const c = Math.cos(angle) * repeat.radius;
      const s = Math.sin(angle) * repeat.radius;
      if (repeat.axis === "x") return [span, c, s];
      if (repeat.axis === "z") return [c, s, span];
      return [c, span, s];
    }
    case "grid": {
      const n = Math.max(1, Math.ceil(Math.sqrt(count)));
      const gx = n === 1 ? 0 : (index % n) / (n - 1) - 0.5;
      const gz = n === 1 ? 0 : Math.floor(index / n) / (n - 1) - 0.5;
      return [gx * 2 * ex, 0, gz * 2 * ez];
    }
  }
}

function add3(a: Vec3, b: Vec3): Vec3 {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}

function expandPart(part: PartSpec): ProceduralInstance[] {
  const base = {
    partId: part.id,
    structureId: part.structureId,
    shape: part.shape,
    scale: part.scale,
    material: part.material,
    cutawayHide: part.cutawayHide,
    outline: part.outline,
    segments: part.segments,
    ...(part.mirrorZ ? { mirrorZ: true } : {}),
  } satisfies Omit<ProceduralInstance, "key" | "position" | "rotation">;

  if (!part.repeat) {
    return [
      {
        ...base,
        key: part.id,
        position: part.position,
        rotation: part.rotation,
      },
    ];
  }

  const rng = createRng(part.repeat.seed);
  const out: ProceduralInstance[] = [];
  for (let i = 0; i < part.repeat.count; i += 1) {
    const offset = repeatOffset(part.repeat, i, rng);
    const jitterStrength = part.repeat.jitter;
    const jitter: Vec3 =
      jitterStrength > 0
        ? [
            (rng() * 2 - 1) * jitterStrength * 0.12,
            (rng() * 2 - 1) * jitterStrength * 0.12,
            (rng() * 2 - 1) * jitterStrength * 0.12,
          ]
        : [0, 0, 0];
    const rotJitter = part.repeat.jitterRotation;
    const rotation: Vec3 =
      rotJitter > 0
        ? [
            part.rotation[0] + (rng() * 2 - 1) * rotJitter,
            part.rotation[1] + (rng() * 2 - 1) * rotJitter,
            part.rotation[2] + (rng() * 2 - 1) * rotJitter,
          ]
        : part.rotation;
    out.push({
      ...base,
      key: `${part.id}#${i}`,
      position: add3(part.position, add3(offset, jitter)),
      rotation,
      repeatIndex: i,
    });
  }
  return out;
}

export function expandProcedural(spec: ProceduralSpec): ProceduralInstance[] {
  return spec.parts.flatMap(expandPart);
}

export function rotatePoint([x, y, z]: Vec3, [rx, ry, rz]: Vec3): Vec3 {
  // Matches Three.js Matrix4.makeRotationFromEuler(..., "XYZ").
  const c1 = Math.cos(rx);
  const s1 = Math.sin(rx);
  const c2 = Math.cos(ry);
  const s2 = Math.sin(ry);
  const c3 = Math.cos(rz);
  const s3 = Math.sin(rz);
  const m11 = c2 * c3;
  const m12 = -c2 * s3;
  const m13 = s2;
  const m21 = c1 * s3 + s1 * s2 * c3;
  const m22 = c1 * c3 - s1 * s2 * s3;
  const m23 = -s1 * c2;
  const m31 = s1 * s3 - c1 * s2 * c3;
  const m32 = s1 * c3 + c1 * s2 * s3;
  const m33 = c1 * c2;
  return [m11 * x + m12 * y + m13 * z, m21 * x + m22 * y + m23 * z, m31 * x + m32 * y + m33 * z];
}

export function computeWorldBounds(instances: ProceduralInstance[]): Bounds {
  if (instances.length === 0) {
    throw new Error("Cannot compute bounds for zero procedural instances");
  }
  const min: Vec3 = [Infinity, Infinity, Infinity];
  const max: Vec3 = [-Infinity, -Infinity, -Infinity];

  for (const instance of instances) {
    const extents = SHAPE_EXTENTS[instance.shape];
    const hx = (extents[0] * instance.scale[0]) / 2;
    const hy = (extents[1] * instance.scale[1]) / 2;
    const hz = (extents[2] * instance.scale[2]) / 2;
    for (const sx of [-1, 1]) {
      for (const sy of [-1, 1]) {
        for (const sz of [-1, 1]) {
          const corner = rotatePoint([hx * sx, hy * sy, hz * sz], instance.rotation);
          const wx = instance.position[0] + corner[0];
          const wy = instance.position[1] + corner[1];
          const wz = instance.position[2] + corner[2];
          if (wx < min[0]) min[0] = wx;
          if (wy < min[1]) min[1] = wy;
          if (wz < min[2]) min[2] = wz;
          if (wx > max[0]) max[0] = wx;
          if (wy > max[1]) max[1] = wy;
          if (wz > max[2]) max[2] = wz;
        }
      }
    }
  }
  return { min, max };
}

export function isFiniteBounds(bounds: Bounds): boolean {
  const values = [...bounds.min, ...bounds.max];
  return values.every((v) => Number.isFinite(v));
}

export function boundsSize(bounds: Bounds): Vec3 {
  return [
    bounds.max[0] - bounds.min[0],
    bounds.max[1] - bounds.min[1],
    bounds.max[2] - bounds.min[2],
  ];
}

/**
 * Canonical normalisation: centre the bounds at the origin, scale the largest
 * dimension to the requested diameter, and record the exact transform so the
 * viewer and the audit report agree. Real-world scale is never inferred.
 */
export function computeNormalization(bounds: Bounds, canonicalDiameter: number): Normalization {
  const size = boundsSize(bounds);
  const maxDim = Math.max(size[0], size[1], size[2]);
  if (!Number.isFinite(maxDim) || maxDim <= 0) {
    throw new Error("Invalid bounds: procedural extent must be finite and non-zero");
  }
  const scale = canonicalDiameter / maxDim;
  const center: Vec3 = [
    (bounds.min[0] + bounds.max[0]) / 2,
    (bounds.min[1] + bounds.max[1]) / 2,
    (bounds.min[2] + bounds.max[2]) / 2,
  ];
  const translation: Vec3 = [-center[0] * scale, -center[1] * scale, -center[2] * scale];
  const normalizedBounds: Bounds = {
    min: [
      (bounds.min[0] - center[0]) * scale,
      (bounds.min[1] - center[1]) * scale,
      (bounds.min[2] - center[2]) * scale,
    ],
    max: [
      (bounds.max[0] - center[0]) * scale,
      (bounds.max[1] - center[1]) * scale,
      (bounds.max[2] - center[2]) * scale,
    ],
  };
  return { scale, translation, sourceBounds: bounds, normalizedBounds, canonicalDiameter };
}

export function structureMeshIndex(
  instances: ProceduralInstance[],
): Map<string, { partIds: Set<string>; instanceKeys: string[]; count: number }> {
  const map = new Map<string, { partIds: Set<string>; instanceKeys: string[]; count: number }>();
  for (const instance of instances) {
    if (!instance.structureId) continue;
    let entry = map.get(instance.structureId);
    if (!entry) {
      entry = { partIds: new Set(), instanceKeys: [], count: 0 };
      map.set(instance.structureId, entry);
    }
    entry.partIds.add(instance.partId);
    entry.instanceKeys.push(instance.key);
    entry.count += 1;
  }
  return map;
}

export type { PartSpec };
