import {
  ACESFilmicToneMapping,
  Box3,
  CircleGeometry,
  Color,
  DirectionalLight,
  DoubleSide,
  Group,
  HemisphereLight,
  Mesh,
  MeshBasicMaterial,
  PerspectiveCamera,
  PMREMGenerator,
  RingGeometry,
  Scene,
  SRGBColorSpace,
  Vector3,
  WebGLRenderer,
  type WebGLRenderTarget,
} from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";
import type { AssetRecord, Specimen } from "@cas/content-registry";
import { CameraDirector } from "./camera";
import type { ViewMode, ViewerEvent, ViewerEventSink, ViewerUnavailableReason } from "./events";
import { exportSceneToGlb, parseGlb } from "./glb";
import { StructureHighlighter } from "./highlight";
import { PointerPicker } from "./interaction";
import { AssetLoadError, loadGlbAsset } from "./loader";
import { initialLoadState, reduceLoadState, type LoadError, type LoadState } from "./load-state";
import {
  buildLoadedScene,
  buildProceduralScene,
  disposeObject3D,
  type BuiltScene,
} from "./scene-builder";
import type { ViewerCapability } from "./types";

export class ViewerCreationError extends Error {
  readonly reason: ViewerUnavailableReason;
  constructor(reason: ViewerUnavailableReason, message: string) {
    super(message);
    this.name = "ViewerCreationError";
    this.reason = reason;
  }
}

export type ViewerControllerOptions = {
  container: HTMLElement;
  onEvent?: ViewerEventSink;
  reduceMotion?: boolean;
  autoRotate?: boolean;
  initialView?: ViewMode;
};

/**
 * Imperative Three.js viewer behind a narrow command/event API. It knows
 * nothing about React, education, persistence, or the app shell.
 */
export class ViewerController {
  readonly capability: ViewerCapability;

  private readonly container: HTMLElement;
  private readonly onEvent: ViewerEventSink | undefined;
  private readonly renderer: WebGLRenderer;
  private readonly scene = new Scene();
  private readonly camera: PerspectiveCamera;
  private readonly controls: OrbitControls;
  private readonly director: CameraDirector;
  private readonly picker: PointerPicker;
  private readonly platform = new Group();
  private readonly ringMaterial: MeshBasicMaterial;
  private readonly discMaterial: MeshBasicMaterial;
  private readonly resizeObserver: ResizeObserver | null;
  private envRenderTarget: WebGLRenderTarget | null = null;
  private built: BuiltScene | null = null;
  private highlighter: StructureHighlighter | null = null;
  private currentSpecimen: Specimen | null = null;
  private currentAsset: AssetRecord | null = null;
  private loadState: LoadState = initialLoadState;
  private loadToken = 0;
  private loadAbort: AbortController | null = null;
  private view: ViewMode = "mesh";
  private focusedId: string | null = null;
  private cutaway = false;
  private autoRotateRequested: boolean;
  private reduceMotion: boolean;
  private disposed = false;
  private contextLost = false;
  private lastFrame = 0;
  private loopActive = false;
  private needsRender = false;
  private dragging = false;
  private readonly scratchBox = new Box3();
  private readonly scratchMeshBox = new Box3();

  constructor(options: ViewerControllerOptions) {
    this.container = options.container;
    this.onEvent = options.onEvent;
    this.reduceMotion = options.reduceMotion ?? false;
    this.autoRotateRequested = options.autoRotate ?? false;
    this.view = options.initialView ?? "mesh";

    let renderer: WebGLRenderer;
    try {
      renderer = new WebGLRenderer({
        antialias: true,
        alpha: true,
        preserveDrawingBuffer: true,
        powerPreference: "high-performance",
      });
    } catch (cause) {
      throw new ViewerCreationError(
        "renderer-failed",
        `Could not create a WebGL renderer: ${cause instanceof Error ? cause.message : String(cause)}`,
      );
    }
    this.renderer = renderer;
    this.capability = readCapability(renderer);

    const width = this.container.clientWidth || 640;
    const height = this.container.clientHeight || 420;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(width, height, false);
    renderer.outputColorSpace = SRGBColorSpace;
    renderer.toneMapping = ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.domElement.className = "cas-canvas";
    renderer.domElement.setAttribute("aria-hidden", "true");
    renderer.domElement.style.display = "block";
    renderer.domElement.style.width = "100%";
    renderer.domElement.style.height = "100%";
    renderer.domElement.style.touchAction = "none";
    this.container.appendChild(renderer.domElement);

    this.camera = new PerspectiveCamera(38, width / height, 0.05, 80);
    this.camera.position.set(2.4, 1.7, 3.4);

    this.controls = new OrbitControls(this.camera, renderer.domElement);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.075;
    this.controls.enablePan = false;
    this.controls.rotateSpeed = 0.7;
    this.controls.zoomSpeed = 0.8;
    this.controls.minDistance = 1.05;
    this.controls.maxDistance = 8.5;
    this.controls.minPolarAngle = Math.PI * 0.12;
    this.controls.maxPolarAngle = Math.PI * 0.88;
    this.controls.autoRotateSpeed = 0.65;
    this.controls.autoRotate = this.autoRotateRequested && !this.reduceMotion;
    this.controls.target.set(0, 0, 0);
    this.controls.addEventListener("start", this.handleControlStart);
    this.controls.addEventListener("change", this.handleControlChange);
    this.controls.addEventListener("end", this.handleControlEnd);

    this.director = new CameraDirector(this.camera, this.controls);
    this.director.setReduceMotion(this.reduceMotion);

    this.setupEnvironment();

    const hemisphere = new HemisphereLight(0xe4f1ff, 0x1e1824, 0.65);
    const key = new DirectionalLight(0xfff1e0, 2.2);
    key.position.set(4.5, 6.5, 5);
    const rim = new DirectionalLight(0x8fd0ff, 1.45);
    rim.position.set(-5, 2.8, -4.5);
    const fill = new DirectionalLight(0xffe8d6, 0.4);
    fill.position.set(-1.5, -3.5, 4);
    this.scene.add(hemisphere, key, rim, fill);

    this.ringMaterial = new MeshBasicMaterial({
      color: new Color("#7cc9d6"),
      transparent: true,
      opacity: 0.22,
      depthWrite: false,
      side: DoubleSide,
    });
    this.discMaterial = new MeshBasicMaterial({
      color: new Color("#7cc9d6"),
      transparent: true,
      opacity: 0.05,
      depthWrite: false,
      side: DoubleSide,
    });
    const ringGeometry = new RingGeometry(1.06, 1.12, 96);
    ringGeometry.rotateX(-Math.PI / 2);
    const discGeometry = new CircleGeometry(1.02, 64);
    discGeometry.rotateX(-Math.PI / 2);
    this.platform.add(new Mesh(ringGeometry, this.ringMaterial));
    this.platform.add(new Mesh(discGeometry, this.discMaterial));
    this.scene.add(this.platform);

    this.picker = new PointerPicker(
      renderer.domElement,
      this.camera,
      () => this.built?.meshes ?? [],
      (structureId) => {
        this.setFocusSilent(structureId);
        if (this.currentSpecimen) {
          this.emit({
            type: "structure-focused",
            specimenId: this.currentSpecimen.id,
            structureId,
          });
        }
      },
    );

    renderer.domElement.addEventListener("webglcontextlost", this.handleContextLost);
    renderer.domElement.addEventListener("webglcontextrestored", this.handleContextRestored);
    document.addEventListener("visibilitychange", this.handleVisibilityChange);

    this.resizeObserver =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(() => this.resize()) : null;
    this.resizeObserver?.observe(this.container);
    window.addEventListener("resize", this.resize);

    this.lastFrame = performance.now();
    this.requestRender();
  }

  getLoadState(): LoadState {
    return this.loadState;
  }

  getCurrentSpecimenId(): string | null {
    return this.currentSpecimen?.id ?? null;
  }

  async setSpecimen(specimen: Specimen, asset: AssetRecord): Promise<void> {
    if (this.disposed) return;
    const token = ++this.loadToken;
    this.loadAbort?.abort();
    this.loadAbort = null;
    this.loadState = reduceLoadState(this.loadState, { type: "start", specimenId: specimen.id });
    this.emitProgress(specimen.id, 0);

    if (asset.kind === "procedural") {
      try {
        const start = performance.now();
        const built = buildProceduralScene(specimen, asset);
        if (token !== this.loadToken || this.disposed) {
          built.dispose();
          return;
        }
        this.applyBuiltScene(built, specimen, asset);
        const buildMs = Math.round(performance.now() - start);
        this.loadState = reduceLoadState(this.loadState, {
          type: "success",
          specimenId: specimen.id,
        });
        this.emitProgress(specimen.id, 1);
        this.emit({
          type: "specimen-ready",
          specimenId: specimen.id,
          meshCount: built.meshCount,
          buildMs,
          source: "procedural",
        });
      } catch (cause) {
        this.fail(
          specimen.id,
          "asset-corrupt",
          `The schematic for ${specimen.name} could not be built: ${cause instanceof Error ? cause.message : String(cause)}`,
          false,
        );
      }
      return;
    }

    const abort = new AbortController();
    this.loadAbort = abort;
    try {
      const object = await loadGlbAsset(asset.uri, (buffer) => parseGlb(buffer, asset), {
        signal: abort.signal,
        onProgress: (progress) => this.emitProgress(specimen.id, progress),
        timeoutMs: 20_000,
        retries: 1,
      });
      if (token !== this.loadToken || this.disposed) {
        disposeObject3D(object);
        return;
      }
      const built = buildLoadedScene(specimen, asset, object);
      this.applyBuiltScene(built, specimen, asset);
      this.loadState = reduceLoadState(this.loadState, {
        type: "success",
        specimenId: specimen.id,
      });
      this.emit({
        type: "specimen-ready",
        specimenId: specimen.id,
        meshCount: built.meshCount,
        buildMs: 0,
        source: "glb",
      });
    } catch (cause) {
      if (token !== this.loadToken || this.disposed) return;
      if (cause instanceof AssetLoadError && cause.code === "cancelled") {
        this.loadState = reduceLoadState(this.loadState, {
          type: "cancel",
          specimenId: specimen.id,
        });
        return;
      }
      const error: LoadError =
        cause instanceof AssetLoadError
          ? { code: cause.code, message: cause.message, retryable: cause.retryable }
          : {
              code: "asset-decode",
              message: cause instanceof Error ? cause.message : String(cause),
              retryable: false,
            };
      this.fail(specimen.id, error.code, error.message, error.retryable);
    }
  }

  reload(): void {
    if (this.currentSpecimen && this.currentAsset) {
      void this.setSpecimen(this.currentSpecimen, this.currentAsset);
    }
  }

  focusStructure(structureId: string | null): number {
    this.focusedId = structureId;
    const count = this.highlighter?.setFocus(structureId) ?? 0;
    if (structureId && this.view === "focus") this.frameStructure(structureId);
    this.requestRender();
    return count;
  }

  setView(view: ViewMode): void {
    this.view = view;
    this.highlighter?.setMode(view);
    if (view === "focus" && this.focusedId) this.frameStructure(this.focusedId);
    this.requestRender();
  }

  setCutaway(enabled: boolean): void {
    this.cutaway = enabled;
    this.highlighter?.setCutaway(enabled);
    this.requestRender();
  }

  setAutoRotate(enabled: boolean): void {
    this.autoRotateRequested = enabled;
    this.controls.autoRotate = enabled && !this.reduceMotion;
    this.requestRender();
  }

  setReduceMotion(enabled: boolean): void {
    this.reduceMotion = enabled;
    this.director.setReduceMotion(enabled);
    this.controls.autoRotate = this.autoRotateRequested && !enabled;
    this.requestRender();
  }

  resetCamera(): void {
    this.director.reset();
    this.requestRender();
  }

  resize(): void {
    if (this.disposed) return;
    const width = this.container.clientWidth || 1;
    const height = this.container.clientHeight || 1;
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / Math.max(height, 1);
    this.camera.updateProjectionMatrix();
    this.requestRender();
  }

  getStats(): { meshCount: number; triangles: number; webgl: string } {
    return {
      meshCount: this.built?.meshCount ?? 0,
      triangles: this.renderer.info.render.triangles,
      webgl: this.capability.api ?? "none",
    };
  }

  captureScreenshot(): Promise<Blob> {
    this.renderer.render(this.scene, this.camera);
    const canvas = this.renderer.domElement;
    return new Promise((resolve, reject) => {
      canvas.toBlob((blob) => {
        if (blob) resolve(blob);
        else reject(new Error("The browser could not encode the screenshot"));
      }, "image/png");
    });
  }

  async exportGlb(): Promise<Blob> {
    if (!this.built) throw new Error("No specimen is currently rendered");
    if (this.currentAsset && !this.currentAsset.export.glb) {
      throw new Error("This specimen's license does not permit model export");
    }
    return exportSceneToGlb(this.built.root);
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.loadAbort?.abort();
    this.stopLoop();
    this.resizeObserver?.disconnect();
    window.removeEventListener("resize", this.resize);
    this.controls.removeEventListener("start", this.handleControlStart);
    this.controls.removeEventListener("change", this.handleControlChange);
    this.controls.removeEventListener("end", this.handleControlEnd);
    this.renderer.domElement.removeEventListener("webglcontextlost", this.handleContextLost);
    this.renderer.domElement.removeEventListener(
      "webglcontextrestored",
      this.handleContextRestored,
    );
    document.removeEventListener("visibilitychange", this.handleVisibilityChange);
    this.picker.dispose();
    this.controls.dispose();
    this.highlighter?.dispose();
    this.built?.dispose();
    for (const child of this.platform.children) {
      if (child instanceof Mesh) child.geometry.dispose();
    }
    this.ringMaterial.dispose();
    this.discMaterial.dispose();
    this.scene.environment = null;
    this.envRenderTarget?.dispose();
    this.envRenderTarget = null;
    this.scene.clear();
    this.renderer.dispose();
    this.renderer.forceContextLoss();
    this.renderer.domElement.remove();
  }

  private applyBuiltScene(built: BuiltScene, specimen: Specimen, asset: AssetRecord): void {
    this.loadAbort = null;
    this.highlighter?.dispose();
    this.built?.dispose();

    this.built = built;
    this.currentSpecimen = specimen;
    this.currentAsset = asset;

    this.scene.add(built.root);
    this.scene.updateMatrixWorld(true);

    this.highlighter = new StructureHighlighter(built, specimen.accent);
    this.highlighter.setMode(this.view);
    this.highlighter.setCutaway(this.cutaway);
    if (
      this.focusedId &&
      !specimen.structures.some((structure) => structure.id === this.focusedId)
    ) {
      this.focusedId = null;
    }
    this.highlighter.setFocus(this.focusedId);

    const normalized = built.normalization.normalizedBounds;
    const center = new Vector3(
      (normalized.min[0] + normalized.max[0]) / 2,
      (normalized.min[1] + normalized.max[1]) / 2,
      (normalized.min[2] + normalized.max[2]) / 2,
    );
    const radius =
      Math.max(
        normalized.max[0] - normalized.min[0],
        normalized.max[1] - normalized.min[1],
        normalized.max[2] - normalized.min[2],
      ) / 2;
    this.director.setHome(radius * 1.08, center);
    this.director.reset();
    this.director.setReduceMotion(this.reduceMotion);

    this.platform.position.set(center.x, normalized.min[1] - 0.055, center.z);
    const platformScale = Math.max(radius * 1.05, 0.75);
    this.platform.scale.setScalar(platformScale);
    this.ringMaterial.color.set(specimen.accent);
    this.discMaterial.color.set(specimen.accent);

    this.camera.updateProjectionMatrix();
    if (this.focusedId && this.view === "focus") {
      this.frameStructure(this.focusedId);
    }
    this.renderer.render(this.scene, this.camera);
    this.needsRender = false;
    if (this.director.isAnimating() || this.controls.autoRotate) {
      this.requestRender();
    } else {
      this.stopLoop();
    }
  }

  private frameStructure(structureId: string): void {
    if (!this.built) return;
    const meshes = this.built.structureMeshes.get(structureId) ?? [];
    if (meshes.length === 0) return;
    this.scene.updateMatrixWorld(true);
    this.scratchBox.makeEmpty();
    for (const mesh of meshes) {
      if (!mesh.visible) continue;
      this.scratchMeshBox.setFromObject(mesh);
      this.scratchBox.union(this.scratchMeshBox);
    }
    this.director.frame(this.scratchBox.isEmpty() ? null : this.scratchBox);
  }

  private setFocusSilent(structureId: string | null): void {
    this.focusedId = structureId;
    this.highlighter?.setFocus(structureId);
    this.requestRender();
  }

  private fail(
    specimenId: string,
    reason: ViewerUnavailableReason,
    message: string,
    retryable: boolean,
  ): void {
    this.loadState = reduceLoadState(this.loadState, {
      type: "failure",
      specimenId,
      error: { code: reason, message, retryable },
    });
    this.emit({
      type: "viewer-error",
      specimenId,
      reason,
      message,
      retryable,
    });
  }

  private emitProgress(specimenId: string, progress: number): void {
    this.loadState = reduceLoadState(this.loadState, {
      type: "progress",
      specimenId,
      progress,
    });
    this.emit({ type: "load-progress", specimenId, progress });
  }

  private emit(event: ViewerEvent): void {
    try {
      this.onEvent?.(event);
    } catch (cause) {
      // A UI listener must never break the render loop.
      console.error("Viewer event listener failed", cause);
    }
  }

  private requestRender(): void {
    this.needsRender = true;
    if (this.disposed || this.contextLost || document.hidden || this.loopActive) return;
    this.loopActive = true;
    this.lastFrame = performance.now();
    this.renderer.setAnimationLoop(this.tick);
  }

  private stopLoop(): void {
    if (!this.loopActive) return;
    this.loopActive = false;
    this.renderer.setAnimationLoop(null);
  }

  private tick = (): void => {
    if (this.disposed || this.contextLost || document.hidden) {
      this.stopLoop();
      return;
    }
    const now = performance.now();
    const delta = Math.min((now - this.lastFrame) / 1000, 0.1);
    this.lastFrame = now;
    const movedByControls = this.controls.update();
    const movedByDirector = this.director.update(delta);
    if (movedByControls || movedByDirector || this.needsRender) {
      this.needsRender = false;
      this.renderer.render(this.scene, this.camera);
    }
    const keepRunning =
      this.dragging ||
      this.controls.autoRotate ||
      this.director.isAnimating() ||
      movedByControls ||
      this.needsRender;
    if (!keepRunning) {
      this.stopLoop();
    }
  };

  private handleControlStart = (): void => {
    this.dragging = true;
    this.director.cancel();
    if (this.autoRotateRequested) {
      this.autoRotateRequested = false;
      this.controls.autoRotate = false;
      this.emit({ type: "auto-rotate-changed", enabled: false });
    }
    this.requestRender();
  };

  private handleControlChange = (): void => {
    this.requestRender();
  };

  private handleControlEnd = (): void => {
    this.dragging = false;
    this.requestRender();
  };

  private handleVisibilityChange = (): void => {
    if (this.disposed || this.contextLost) return;
    if (document.hidden) {
      this.stopLoop();
    } else {
      this.requestRender();
    }
  };

  private handleContextLost = (event: Event): void => {
    event.preventDefault();
    this.contextLost = true;
    this.stopLoop();
    this.emit({
      type: "viewer-unavailable",
      reason: "context-lost",
      message:
        "The graphics context was lost. Text content and the structure list are still available; restore will be attempted automatically.",
    });
  };

  private handleContextRestored = (): void => {
    if (this.disposed) return;
    this.contextLost = false;
    this.setupEnvironment();
    this.requestRender();
    this.emit({ type: "context-restored" });
    if (this.currentSpecimen && this.currentAsset) {
      void this.setSpecimen(this.currentSpecimen, this.currentAsset);
    }
  };

  private setupEnvironment(): void {
    this.scene.environment = null;
    this.envRenderTarget?.dispose();
    this.envRenderTarget = null;
    try {
      const pmrem = new PMREMGenerator(this.renderer);
      const roomEnv = new RoomEnvironment();
      this.envRenderTarget = pmrem.fromScene(roomEnv, 0.04);
      this.scene.environment = this.envRenderTarget.texture;
      this.scene.environmentIntensity = 0.5;
      roomEnv.dispose();
      pmrem.dispose();
    } catch {
      // Minimal/software WebGL contexts can fall back cleanly to direct studio lights.
    }
  }
}

function readCapability(renderer: WebGLRenderer): ViewerCapability {
  const context = renderer.getContext();
  let rendererName: string | null = null;
  try {
    const debug = context.getExtension("WEBGL_debug_renderer_info");
    if (debug) rendererName = String(context.getParameter(debug.UNMASKED_RENDERER_WEBGL));
  } catch {
    rendererName = null;
  }
  return {
    supported: true,
    api: renderer.capabilities.isWebGL2 ? "webgl2" : "webgl1",
    reason: null,
    maxTextureSize: renderer.capabilities.maxTextureSize,
    renderer: rendererName,
  };
}
