import { Color, DoubleSide, LineSegments, MeshStandardMaterial } from "three";
import type { Material, Mesh } from "three";
import type { ViewMode } from "./events";
import type { BuiltScene } from "./scene-builder";

/**
 * Applies evidence-mapped structure highlighting. Every highlight corresponds
 * to authored, registry-declared meshes — never to generated vertex colours.
 */
export class StructureHighlighter {
  private readonly scene: BuiltScene;
  private readonly accent: Color;
  private readonly ghost: MeshStandardMaterial;
  private readonly selectedClones = new Map<Material, Material>();
  private selectedId: string | null = null;
  private mode: ViewMode = "mesh";
  private cutaway = false;

  constructor(scene: BuiltScene, accentHex: string) {
    this.scene = scene;
    this.accent = new Color(accentHex);
    this.ghost = new MeshStandardMaterial({
      color: new Color("#8fa3ad"),
      roughness: 0.95,
      metalness: 0,
      transparent: true,
      opacity: 0.055,
      depthWrite: false,
      side: DoubleSide,
    });
    this.ghost.name = "ghost:context";
  }

  setFocus(structureId: string | null): number {
    this.selectedId = structureId;
    this.apply();
    return this.selectedId ? (this.scene.structureMeshes.get(this.selectedId)?.length ?? 0) : 0;
  }

  getFocus(): string | null {
    return this.selectedId;
  }

  setMode(mode: ViewMode): void {
    this.mode = mode;
    this.apply();
  }

  setCutaway(enabled: boolean): void {
    this.cutaway = enabled;
    this.apply();
  }

  dispose(): void {
    for (const mesh of this.scene.meshes) {
      mesh.material = mesh.userData.baseMaterial as Material | Material[];
      mesh.visible = true;
      this.setOutlineVisibility(mesh, true);
    }
    for (const clone of this.selectedClones.values()) clone.dispose();
    this.selectedClones.clear();
    this.ghost.dispose();
  }

  private apply(): void {
    const selected = this.selectedId ? (this.scene.structureMeshes.get(this.selectedId) ?? []) : [];
    const selectedSet = new Set<Mesh>(selected);
    const focusActive = this.mode === "focus" && this.selectedId !== null;

    for (const mesh of this.scene.meshes) {
      const isSelected = selectedSet.has(mesh);
      const base = mesh.userData.baseMaterial as Material | Material[];
      mesh.material = isSelected ? this.selectedMaterials(base) : focusActive ? this.ghost : base;
      const hiddenByCutaway = this.cutaway && Boolean(mesh.userData.cutawayHide);
      mesh.visible = !hiddenByCutaway || isSelected;
      this.setOutlineVisibility(mesh, !focusActive || isSelected);
    }
  }

  private selectedMaterials(base: Material | Material[]): Material | Material[] {
    return Array.isArray(base)
      ? base.map((material) => this.selectedMaterial(material))
      : this.selectedMaterial(base);
  }

  private selectedMaterial(base: Material): Material {
    const cached = this.selectedClones.get(base);
    if (cached) return cached;

    const clone = base.clone();
    if (clone instanceof MeshStandardMaterial) {
      clone.emissive = this.accent.clone().multiplyScalar(0.55);
      clone.emissiveIntensity = Math.max(0.38, clone.emissiveIntensity);
      clone.color.lerp(this.accent, 0.2);
      if (clone.transparent && clone.opacity < 0.35) {
        clone.opacity = Math.min(0.45, clone.opacity + 0.16);
      }
    }
    clone.name = `highlight:${base.name || "material"}`;
    this.selectedClones.set(base, clone);
    return clone;
  }

  private setOutlineVisibility(mesh: Mesh, visible: boolean): void {
    for (const child of mesh.children) {
      if (child instanceof LineSegments) child.visible = visible;
    }
  }
}
