import { catalogAssets, specimens } from "./catalog";
import { getProceduralSpec } from "./procedural-loader";
import type { AssetRecord, ProceduralSpec } from "./schema";

export { specimens };

export const proceduralSpecs: Record<string, ProceduralSpec> = Object.fromEntries(
  specimens.map((specimen) => {
    const spec = getProceduralSpec(specimen.assetId);
    if (!spec) {
      throw new Error(`Missing procedural spec for asset ${specimen.assetId}`);
    }
    return [specimen.assetId, spec];
  }),
);

export const assets: AssetRecord[] = catalogAssets.map((base) => {
  const procedural = proceduralSpecs[base.id];
  if (!procedural) {
    throw new Error(`Missing procedural spec for asset ${base.id}`);
  }
  return { ...base, procedural };
});
