import {
  BoxGeometry,
  BufferGeometry,
  CapsuleGeometry,
  CatmullRomCurve3,
  ConeGeometry,
  CylinderGeometry,
  ExtrudeGeometry,
  Float32BufferAttribute,
  LatheGeometry,
  Quaternion,
  Shape,
  SphereGeometry,
  TorusGeometry,
  TorusKnotGeometry,
  TubeGeometry,
  Vector2,
  Vector3,
} from "three";
import {
  evalBrainHemispherePoint,
  evalBrainLobePoint,
  evalBrainstemPoint,
  evalCerebellumPoint,
  evalCorpusCallosumSection,
  evalHippocampusSection,
  evalLimbicArchSection,
  evalVentricleHornSection,
  type BrainLobeRegion,
  type ProceduralInstance,
  type ProceduralShape,
  type SweptSection,
} from "@cas/content-registry";

function normalizeToExtent(
  geometry: BufferGeometry,
  target: [number, number, number],
): BufferGeometry {
  geometry.computeBoundingBox();
  const box = geometry.boundingBox;
  if (box) {
    const center = box.getCenter(new Vector3());
    geometry.translate(-center.x, -center.y, -center.z);
    const size = box.getSize(new Vector3());
    geometry.scale(
      size.x > 1e-5 ? target[0] / size.x : 1,
      size.y > 1e-5 ? target[1] / size.y : 1,
      size.z > 1e-5 ? target[2] / size.z : 1,
    );
  }
  geometry.computeVertexNormals();
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
  return geometry;
}

function buildRoundedBox(seg: number): BufferGeometry {
  const half = 0.43;
  const radius = 0.12;
  const shape = new Shape();
  shape.moveTo(-half + radius, -half);
  shape.lineTo(half - radius, -half);
  shape.quadraticCurveTo(half, -half, half, -half + radius);
  shape.lineTo(half, half - radius);
  shape.quadraticCurveTo(half, half, half - radius, half);
  shape.lineTo(-half + radius, half);
  shape.quadraticCurveTo(-half, half, -half, half - radius);
  shape.lineTo(-half, -half + radius);
  shape.quadraticCurveTo(-half, -half, -half + radius, -half);

  const geometry = new ExtrudeGeometry(shape, {
    depth: 0.72,
    bevelEnabled: true,
    bevelSegments: Math.max(3, Math.round(seg / 6)),
    steps: 1,
    bevelSize: 0.14,
    bevelThickness: 0.14,
    curveSegments: Math.max(4, Math.round(seg / 4)),
  });
  return normalizeToExtent(geometry, [1, 1, 1]);
}

function buildBiconcave(seg: number): BufferGeometry {
  const steps = Math.max(18, Math.round(seg / 2));
  const halfY = (u: number) => {
    const clamped = Math.min(0.9999, Math.max(0, u));
    const u2 = clamped * clamped;
    return Math.sqrt(Math.max(0, 1 - u2)) * (0.21 + 2.0 * u2 - 1.12 * u2 * u2);
  };
  const points: Vector2[] = [];
  for (let i = 0; i <= steps; i += 1) {
    const u = Math.max(0.002, i / steps);
    points.push(new Vector2(u * 0.5, -halfY(u)));
  }
  for (let i = steps - 1; i >= 0; i -= 1) {
    const u = Math.max(0.002, i / steps);
    points.push(new Vector2(u * 0.5, halfY(u)));
  }
  const geometry = new LatheGeometry(points, seg);
  return normalizeToExtent(geometry, [1, 1, 1]);
}

function buildCurvedSheet(seg: number): BufferGeometry {
  const arcSegs = Math.max(12, Math.round(seg / 2));
  const startAngle = (32 * Math.PI) / 180;
  const endAngle = (148 * Math.PI) / 180;
  const outerR = 0.56;
  const innerR = 0.42;
  const shape = new Shape();
  shape.moveTo(Math.cos(startAngle) * outerR, Math.sin(startAngle) * outerR);
  for (let i = 1; i <= arcSegs; i += 1) {
    const angle = startAngle + ((endAngle - startAngle) * i) / arcSegs;
    shape.lineTo(Math.cos(angle) * outerR, Math.sin(angle) * outerR);
  }
  const endMidR = (outerR + innerR) / 2;
  shape.quadraticCurveTo(
    Math.cos(endAngle + 0.08) * endMidR,
    Math.sin(endAngle + 0.08) * endMidR,
    Math.cos(endAngle) * innerR,
    Math.sin(endAngle) * innerR,
  );
  for (let i = arcSegs - 1; i >= 0; i -= 1) {
    const angle = startAngle + ((endAngle - startAngle) * i) / arcSegs;
    shape.lineTo(Math.cos(angle) * innerR, Math.sin(angle) * innerR);
  }
  shape.quadraticCurveTo(
    Math.cos(startAngle - 0.08) * endMidR,
    Math.sin(startAngle - 0.08) * endMidR,
    Math.cos(startAngle) * outerR,
    Math.sin(startAngle) * outerR,
  );
  const geometry = new ExtrudeGeometry(shape, {
    depth: 0.72,
    bevelEnabled: true,
    bevelThickness: 0.06,
    bevelSize: 0.05,
    bevelSegments: 3,
    curveSegments: arcSegs,
  });
  return normalizeToExtent(geometry, [1, 0.4, 1]);
}

function buildTubeHelix(seg: number): BufferGeometry {
  const curvePoints: Vector3[] = [];
  const totalPoints = 64;
  for (let i = 0; i < totalPoints; i += 1) {
    const t = i / (totalPoints - 1);
    const x = t - 0.5;
    const angle = t * Math.PI * 2 * 2.5;
    const ramp = Math.sin(Math.min(1, (1 - t) * 2.4) * (Math.PI / 2));
    const radius = 0.02 + 0.15 * ramp;
    curvePoints.push(new Vector3(x, Math.cos(angle) * radius, Math.sin(angle) * radius));
  }
  const curve = new CatmullRomCurve3(curvePoints);
  const tubularSegments = Math.max(48, seg * 2);
  const radialSegments = Math.max(8, Math.round(seg / 3));
  const geometry = new TubeGeometry(curve, tubularSegments, 0.026, radialSegments, false);
  return normalizeToExtent(geometry, [1, 0.4, 0.4]);
}

function buildOrganicBlob(seg: number): BufferGeometry {
  const geometry = new SphereGeometry(0.5, seg, Math.max(10, Math.round(seg / 2)));
  const position = geometry.attributes.position;
  if (position) {
    const vec = new Vector3();
    for (let i = 0; i < position.count; i += 1) {
      vec.fromBufferAttribute(position, i);
      const len = vec.length();
      if (len > 1e-5) {
        const nx = vec.x / len;
        const ny = vec.y / len;
        const nz = vec.z / len;
        const displacement =
          1 +
          0.065 * Math.sin(3.0 * nx + 0.4) * Math.cos(2.0 * ny) +
          0.05 * Math.sin(2.5 * ny + 3.0 * nz) +
          0.04 * Math.cos(3.0 * nz - 2.0 * nx);
        vec.multiplyScalar(displacement);
        position.setXYZ(i, vec.x, vec.y, vec.z);
      }
    }
    position.needsUpdate = true;
  }
  return normalizeToExtent(geometry, [1, 1, 1]);
}

function buildTaperedBranch(seg: number): BufferGeometry {
  const points: Vector2[] = [];
  const baseSteps = 6;
  const shaftSteps = 12;
  const tipSteps = 6;
  const baseRadius = 0.5;
  const tipRadius = 0.15;
  const baseCapHeight = 0.12;
  const tipCapHeight = 0.08;

  for (let i = 0; i <= baseSteps; i += 1) {
    const theta = (i / baseSteps) * (Math.PI / 2);
    const r = Math.max(0.002, Math.sin(theta) * baseRadius);
    const y = -0.5 + (1 - Math.cos(theta)) * baseCapHeight;
    points.push(new Vector2(r, y));
  }
  for (let i = 1; i < shaftSteps; i += 1) {
    const t = i / shaftSteps;
    const blend = 0.5 - 0.5 * Math.cos(t * Math.PI);
    const r = baseRadius + (tipRadius - baseRadius) * blend;
    const y = -0.5 + baseCapHeight + t * (1 - baseCapHeight - tipCapHeight);
    points.push(new Vector2(r, y));
  }
  for (let i = 0; i <= tipSteps; i += 1) {
    const theta = (i / tipSteps) * (Math.PI / 2);
    const r = Math.max(0.002, Math.cos(theta) * tipRadius);
    const y = 0.5 - tipCapHeight + Math.sin(theta) * tipCapHeight;
    points.push(new Vector2(r, y));
  }
  const geometry = new LatheGeometry(points, seg);
  return normalizeToExtent(geometry, [1, 1, 1]);
}

function deformSphere(
  seg: number,
  evaluator: (sx: number, sy: number, sz: number) => [number, number, number],
): BufferGeometry {
  const widthSegs = Math.max(6, Math.round(seg));
  const heightSegs = Math.max(14, Math.round(widthSegs * 0.65));
  const geometry = new SphereGeometry(1, widthSegs, heightSegs);
  const position = geometry.attributes.position;
  if (position) {
    for (let i = 0; i < position.count; i += 1) {
      const [px, py, pz] = evaluator(position.getX(i), position.getY(i), position.getZ(i));
      position.setXYZ(i, px, py, pz);
    }
    position.needsUpdate = true;
  }
  return normalizeToExtent(geometry, [1, 1, 1]);
}

function buildBrainLobe(seg: number, region: BrainLobeRegion): BufferGeometry {
  return deformSphere(seg, (sx, sy, sz) => evalBrainLobePoint(region, sx, sy, sz));
}

function buildBrainCutoutHemisphere(seg: number): BufferGeometry {
  return deformSphere(seg, (sx, sy, sz) =>
    evalBrainHemispherePoint(sx, sy, sz, { cutawayRecess: true }),
  );
}

function buildCerebellumLobe(seg: number): BufferGeometry {
  return deformSphere(seg, (sx, sy, sz) => evalCerebellumPoint(sx, sy, sz));
}

function buildBrainstemCore(seg: number): BufferGeometry {
  const radialSegs = Math.max(12, Math.round(seg));
  const heightSegs = Math.max(20, Math.round(seg * 0.85));
  const ringStride = radialSegs + 1;
  const positions: number[] = [];
  const indices: number[] = [];

  for (let j = 0; j <= heightSegs; j += 1) {
    const v = j / heightSegs;
    for (let i = 0; i <= radialSegs; i += 1) {
      const u = i / radialSegs;
      const [px, py, pz] = evalBrainstemPoint(u, v);
      positions.push(px, py, pz);
    }
  }

  for (let j = 0; j < heightSegs; j += 1) {
    for (let i = 0; i < radialSegs; i += 1) {
      const a = j * ringStride + i;
      const b = a + 1;
      const c = (j + 1) * ringStride + i + 1;
      const d = (j + 1) * ringStride + i;
      indices.push(a, d, b, b, d, c);
    }
  }

  // Smooth closed bottom and top pole caps.
  const botCenterIdx = positions.length / 3;
  let bx = 0;
  let by = 0;
  let bz = 0;
  for (let i = 0; i < radialSegs; i += 1) {
    bx += positions[i * 3]!;
    by += positions[i * 3 + 1]!;
    bz += positions[i * 3 + 2]!;
  }
  positions.push(bx / radialSegs, by / radialSegs - 0.015, bz / radialSegs);
  for (let i = 0; i < radialSegs; i += 1) {
    indices.push(botCenterIdx, i, i + 1);
  }

  const topRowOffset = heightSegs * ringStride;
  const topCenterIdx = positions.length / 3;
  let tx = 0;
  let ty = 0;
  let tz = 0;
  for (let i = 0; i < radialSegs; i += 1) {
    const idx = (topRowOffset + i) * 3;
    tx += positions[idx]!;
    ty += positions[idx + 1]!;
    tz += positions[idx + 2]!;
  }
  positions.push(tx / radialSegs, ty / radialSegs + 0.015, tz / radialSegs);
  for (let i = 0; i < radialSegs; i += 1) {
    indices.push(topCenterIdx, topRowOffset + i + 1, topRowOffset + i);
  }

  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new Float32BufferAttribute(positions, 3));
  geometry.setIndex(indices);
  return normalizeToExtent(geometry, [1, 1, 1]);
}

function buildSweptOrgan(
  seg: number,
  evalSection: (t: number) => SweptSection,
  options: { radialSegments?: number; ridgeAmp?: number; ridgeFreq?: number } = {},
): BufferGeometry {
  const steps = Math.max(24, Math.round(seg));
  const radialSegs = options.radialSegments ?? Math.max(12, Math.round(seg * 0.5));
  const ridgeAmp = options.ridgeAmp ?? 0;
  const ridgeFreq = options.ridgeFreq ?? 0;

  const sections: SweptSection[] = [];
  const centers: Vector3[] = [];
  for (let k = 0; k <= steps; k += 1) {
    const section = evalSection(k / steps);
    sections.push(section);
    centers.push(new Vector3(...section.point));
  }

  const tangents: Vector3[] = [];
  for (let k = 0; k <= steps; k += 1) {
    const prev = centers[Math.max(0, k - 1)]!;
    const next = centers[Math.min(steps, k + 1)]!;
    const tan = next.clone().sub(prev);
    if (tan.lengthSq() < 1e-10) tan.set(1, 0, 0);
    else tan.normalize();
    tangents.push(tan);
  }

  // Parallel-transport (Bishop) frames along the 3D spine so tubes never twist.
  const normals: Vector3[] = [];
  const binormals: Vector3[] = [];
  const t0 = tangents[0]!;
  const ref = Math.abs(t0.z) < 0.9 ? new Vector3(0, 0, 1) : new Vector3(0, 1, 0);
  const n0 = ref.clone().cross(t0).normalize();
  const b0 = t0.clone().cross(n0).normalize();
  normals.push(n0);
  binormals.push(b0);

  const q = new Quaternion();
  for (let k = 1; k <= steps; k += 1) {
    q.setFromUnitVectors(tangents[k - 1]!, tangents[k]!);
    const nk = normals[k - 1]!.clone().applyQuaternion(q).normalize();
    const bk = tangents[k]!.clone().cross(nk).normalize();
    normals.push(nk);
    binormals.push(bk);
  }

  const positions: number[] = [];
  const indices: number[] = [];
  const ringStride = radialSegs + 1;

  const pushEllipticRing = (
    center: Vector3,
    tan: Vector3,
    norm: Vector3,
    binorm: Vector3,
    rx: number,
    ry: number,
    axialOffset: number,
    radialScale: number,
    kIndex: number,
  ) => {
    for (let i = 0; i <= radialSegs; i += 1) {
      const angle = (i / radialSegs) * Math.PI * 2;
      const ca = Math.cos(angle);
      const sa = Math.sin(angle);
      const ridge =
        ridgeAmp > 0
          ? 1 + ridgeAmp * Math.cos(angle * ridgeFreq) * (1 - (kIndex / steps) * 0.6)
          : 1;
      const p = center
        .clone()
        .addScaledVector(tan, axialOffset)
        .addScaledVector(norm, ca * rx * radialScale * ridge)
        .addScaledVector(binorm, sa * ry * radialScale * ridge);
      positions.push(p.x, p.y, p.z);
    }
  };

  // Start cap bevel ring -> main spine rings 0..steps -> end cap bevel ring.
  const first = sections[0]!;
  const startCapDepth = Math.min(first.rx, first.ry) * 0.55;
  pushEllipticRing(
    centers[0]!,
    tangents[0]!,
    normals[0]!,
    binormals[0]!,
    first.rx,
    first.ry,
    -Math.SQRT1_2 * startCapDepth,
    Math.SQRT1_2,
    0,
  );

  for (let k = 0; k <= steps; k += 1) {
    const section = sections[k]!;
    pushEllipticRing(
      centers[k]!,
      tangents[k]!,
      normals[k]!,
      binormals[k]!,
      section.rx,
      section.ry,
      0,
      1,
      k,
    );
  }

  const last = sections[steps]!;
  const endCapDepth = Math.min(last.rx, last.ry) * 0.55;
  pushEllipticRing(
    centers[steps]!,
    tangents[steps]!,
    normals[steps]!,
    binormals[steps]!,
    last.rx,
    last.ry,
    Math.SQRT1_2 * endCapDepth,
    Math.SQRT1_2,
    steps,
  );

  const totalRings = steps + 3;
  for (let k = 0; k < totalRings - 1; k += 1) {
    for (let i = 0; i < radialSegs; i += 1) {
      const a = k * ringStride + i;
      const b = a + 1;
      const c = (k + 1) * ringStride + i + 1;
      const d = (k + 1) * ringStride + i;
      indices.push(a, b, d, b, c, d);
    }
  }

  const startPoleIdx = positions.length / 3;
  const sp = centers[0]!.clone().addScaledVector(tangents[0]!, -startCapDepth);
  positions.push(sp.x, sp.y, sp.z);
  for (let i = 0; i < radialSegs; i += 1) {
    indices.push(startPoleIdx, i + 1, i);
  }

  const endPoleIdx = positions.length / 3;
  const ep = centers[steps]!.clone().addScaledVector(tangents[steps]!, endCapDepth);
  positions.push(ep.x, ep.y, ep.z);
  const lastRingStart = (totalRings - 1) * ringStride;
  for (let i = 0; i < radialSegs; i += 1) {
    indices.push(endPoleIdx, lastRingStart + i, lastRingStart + i + 1);
  }

  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new Float32BufferAttribute(positions, 3));
  geometry.setIndex(indices);
  return normalizeToExtent(geometry, [1, 1, 1]);
}

function mirrorGeometryZ(source: BufferGeometry): BufferGeometry {
  const geometry = source.clone();
  const position = geometry.attributes.position;
  if (position) {
    for (let i = 0; i < position.count; i += 1) {
      position.setZ(i, -position.getZ(i));
    }
    position.needsUpdate = true;
  }

  const index = geometry.getIndex();
  if (index) {
    for (let i = 0; i + 2 < index.count; i += 3) {
      const b = index.getX(i + 1);
      const c = index.getX(i + 2);
      index.setX(i + 1, c);
      index.setX(i + 2, b);
    }
    index.needsUpdate = true;
  } else if (position) {
    for (let i = 0; i + 2 < position.count; i += 3) {
      const bx = position.getX(i + 1);
      const by = position.getY(i + 1);
      const bz = position.getZ(i + 1);
      position.setXYZ(i + 1, position.getX(i + 2), position.getY(i + 2), position.getZ(i + 2));
      position.setXYZ(i + 2, bx, by, bz);
    }
    position.needsUpdate = true;
  }

  geometry.computeVertexNormals();
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
  return geometry;
}

/** Per-scene geometry cache. Two compare viewports never share GPU resources. */
export function createGeometryCache() {
  const cache = new Map<string, BufferGeometry>();

  function get(shape: ProceduralShape, segments: number, mirrorZ = false): BufferGeometry {
    const key = `${shape}:${segments}:${mirrorZ ? "mz" : "std"}`;
    const existing = cache.get(key);
    if (existing) return existing;

    if (mirrorZ) {
      const base = get(shape, segments, false);
      const mirrored = mirrorGeometryZ(base);
      cache.set(key, mirrored);
      return mirrored;
    }

    const seg = Math.max(6, Math.round(segments));
    let geometry: BufferGeometry;
    switch (shape) {
      case "sphere":
        geometry = new SphereGeometry(0.5, seg, Math.max(8, Math.round(seg / 2)));
        break;
      case "box":
        geometry = new BoxGeometry(1, 1, 1);
        break;
      case "cylinder":
        geometry = new CylinderGeometry(0.5, 0.5, 1, seg, 1, false);
        break;
      case "capsule":
        geometry = new CapsuleGeometry(0.5, 1, Math.max(4, Math.round(seg / 6)), seg);
        break;
      case "cone":
        geometry = new ConeGeometry(0.5, 1, seg);
        break;
      case "torus":
        geometry = new TorusGeometry(0.35, 0.15, Math.max(8, Math.round(seg / 2)), seg);
        break;
      case "torusKnot":
        geometry = new TorusKnotGeometry(
          0.35,
          0.06,
          Math.min(320, seg * 3),
          Math.max(6, Math.round(seg / 3)),
        );
        break;
      case "disc":
        geometry = new CylinderGeometry(0.5, 0.5, 0.12, seg);
        break;
      case "roundedBox":
        geometry = buildRoundedBox(seg);
        break;
      case "biconcave":
        geometry = buildBiconcave(seg);
        break;
      case "curvedSheet":
        geometry = buildCurvedSheet(seg);
        break;
      case "tubeHelix":
        geometry = buildTubeHelix(seg);
        break;
      case "organicBlob":
        geometry = buildOrganicBlob(seg);
        break;
      case "taperedBranch":
        geometry = buildTaperedBranch(seg);
        break;
      case "brainFrontalLobe":
        geometry = buildBrainLobe(seg, "frontal");
        break;
      case "brainMotorCortex":
        geometry = buildBrainLobe(seg, "motor");
        break;
      case "brainSensoryCortex":
        geometry = buildBrainLobe(seg, "sensory");
        break;
      case "brainParietalLobe":
        geometry = buildBrainLobe(seg, "parietal");
        break;
      case "brainTemporalLobe":
        geometry = buildBrainLobe(seg, "temporal");
        break;
      case "brainOccipitalLobe":
        geometry = buildBrainLobe(seg, "occipital");
        break;
      case "brainCutoutHemisphere":
        geometry = buildBrainCutoutHemisphere(seg);
        break;
      case "cerebellumLobe":
        geometry = buildCerebellumLobe(seg);
        break;
      case "brainstemCore":
        geometry = buildBrainstemCore(seg);
        break;
      case "corpusCallosum":
        geometry = buildSweptOrgan(seg, evalCorpusCallosumSection, {
          radialSegments: Math.max(14, Math.round(seg * 0.5)),
        });
        break;
      case "limbicArch":
        geometry = buildSweptOrgan(seg, evalLimbicArchSection, {
          radialSegments: Math.max(12, Math.round(seg * 0.45)),
        });
        break;
      case "hippocampusArch":
        geometry = buildSweptOrgan(seg, evalHippocampusSection, {
          radialSegments: Math.max(14, Math.round(seg * 0.5)),
          ridgeAmp: 0.08,
          ridgeFreq: 5,
        });
        break;
      case "ventricleHorn":
        geometry = buildSweptOrgan(seg, evalVentricleHornSection, {
          radialSegments: Math.max(12, Math.round(seg * 0.45)),
        });
        break;
    }
    cache.set(key, geometry);
    return geometry;
  }

  function forInstance(instance: ProceduralInstance): BufferGeometry {
    return get(instance.shape, instance.segments, Boolean(instance.mirrorZ));
  }

  function dispose(): void {
    for (const geometry of cache.values()) geometry.dispose();
    cache.clear();
  }

  return { get, forInstance, dispose };
}

export type GeometryCache = ReturnType<typeof createGeometryCache>;
