import {
  Color,
  DoubleSide,
  FrontSide,
  LineBasicMaterial,
  MeshPhysicalMaterial,
  type Side,
} from "three";
import type { MaterialSpec } from "@cas/content-registry";

/**
 * Material policy: procedural specimens always use the authored "neutral
 * studio" treatment. Colour is authored per structure, not generated from
 * biological data, and is labelled as schematic in the UI.
 */
export function createMaterialCache() {
  const cache = new Map<string, MeshPhysicalMaterial>();
  const lineCache = new Map<string, LineBasicMaterial>();

  function get(spec: MaterialSpec): MeshPhysicalMaterial {
    const key = JSON.stringify(spec);
    const existing = cache.get(key);
    if (existing) return existing;

    const transparent = spec.opacity < 1;
    const isTranslucent = spec.opacity < 0.85;
    const side: Side = transparent ? DoubleSide : FrontSide;
    const clearcoat = isTranslucent
      ? Math.max(spec.clearcoat ?? 0, 0.55)
      : spec.flatShading
        ? 0
        : Math.max(spec.clearcoat ?? 0, 0.16);
    const clearcoatRoughness = isTranslucent
      ? Math.min(spec.clearcoatRoughness ?? 0.25, 0.18)
      : (spec.clearcoatRoughness ?? 0.25);

    const material = new MeshPhysicalMaterial({
      color: new Color(spec.color),
      roughness: spec.roughness,
      metalness: spec.metalness,
      transparent,
      opacity: spec.opacity,
      depthWrite: !isTranslucent,
      side,
      flatShading: spec.flatShading,
      emissive: new Color(spec.emissive ?? "#000000"),
      emissiveIntensity: spec.emissiveIntensity,
      clearcoat,
      clearcoatRoughness,
      ...(isTranslucent ? { ior: 1.38, reflectivity: 0.72 } : {}),
    });
    material.name = `schematic:${spec.color}`;
    cache.set(key, material);
    return material;
  }

  function line(color: string, opacity = 0.55): LineBasicMaterial {
    const key = `${color}:${opacity}`;
    const existing = lineCache.get(key);
    if (existing) return existing;
    const material = new LineBasicMaterial({
      color: new Color(color),
      transparent: true,
      opacity,
      depthWrite: false,
    });
    lineCache.set(key, material);
    return material;
  }

  function dispose(): void {
    for (const material of cache.values()) material.dispose();
    for (const material of lineCache.values()) material.dispose();
    cache.clear();
    lineCache.clear();
  }

  return { get, line, dispose };
}

export type MaterialCache = ReturnType<typeof createMaterialCache>;
