import { forwardRef, memo, useEffect, useImperativeHandle, useRef, type ReactNode } from "react";
import { detectViewerCapability } from "@cas/viewer-capability";
import {
  ViewerController,
  ViewerCreationError,
  type ViewerCapability,
  type ViewerEvent,
  type ViewerEventSink,
} from "@cas/viewer-core";
import type { AssetRecord, Specimen } from "@cas/content-registry";
import type { SceneStore } from "./scene-store";

export type ViewerReadyInfo = {
  specimenId: string;
  meshCount: number;
  buildMs: number;
  source: "procedural" | "glb";
  triangles: number;
  webgl: string;
};

export type ViewerUnavailableInfo = {
  reason: string;
  message: string;
  capability: ViewerCapability | null;
};

export type ViewerHandle = {
  screenshot: () => Promise<Blob>;
  exportGlb: () => Promise<Blob>;
  reload: () => void;
  resetCamera: () => void;
  focusStructure: (structureId: string | null) => void;
};

export type ViewerHostProps = {
  specimen: Specimen;
  asset: AssetRecord;
  store: SceneStore;
  reduceMotion?: boolean;
  className?: string;
  onReady?: (info: ViewerReadyInfo) => void;
  onUnavailable?: (info: ViewerUnavailableInfo) => void;
  children?: ReactNode;
};

/** Thin React adapter: mounts the imperative viewer and syncs scene commands. */
export const ViewerHost = memo(
  forwardRef<ViewerHandle, ViewerHostProps>(function ViewerHost(
    { specimen, asset, store, reduceMotion = false, className, onReady, onUnavailable },
    ref,
  ) {
    const containerRef = useRef<HTMLDivElement>(null);
    const controllerRef = useRef<ViewerController | null>(null);
    const loadedRef = useRef<string | null>(null);
    const capabilityRef = useRef<ViewerCapability | null>(null);
    const specimenRef = useRef(specimen);
    const assetRef = useRef(asset);
    const reduceMotionRef = useRef(reduceMotion);
    const callbacksRef = useRef({ onReady, onUnavailable });

    specimenRef.current = specimen;
    assetRef.current = asset;
    reduceMotionRef.current = reduceMotion;
    callbacksRef.current = { onReady, onUnavailable };

    useEffect(() => {
      const container = containerRef.current;
      if (!container) return;

      const capability = detectViewerCapability(container.ownerDocument);
      capabilityRef.current = capability;
      if (!capability.supported) {
        const message = capability.reason ?? "WebGL is not available in this browser.";
        store.getState().markUnavailable("webgl-unsupported", message);
        callbacksRef.current.onUnavailable?.({
          reason: "webgl-unsupported",
          message,
          capability,
        });
        return;
      }

      const handleEvent: ViewerEventSink = (event: ViewerEvent) => {
        switch (event.type) {
          case "load-progress":
            store.getState().setProgress(event.progress);
            break;
          case "specimen-ready": {
            const controller = controllerRef.current;
            const stats = controller?.getStats();
            store.getState().markReady(event.meshCount);
            callbacksRef.current.onReady?.({
              specimenId: event.specimenId,
              meshCount: event.meshCount,
              buildMs: event.buildMs,
              source: event.source,
              triangles: stats?.triangles ?? 0,
              webgl: stats?.webgl ?? "none",
            });
            break;
          }
          case "structure-focused":
            store.getState().setFocusedStructure(event.structureId);
            break;
          case "viewer-error":
            store.getState().fail({
              code: event.reason,
              message: event.message,
              retryable: event.retryable,
            });
            break;
          case "viewer-unavailable":
            store.getState().markUnavailable(event.reason, event.message);
            callbacksRef.current.onUnavailable?.({
              reason: event.reason,
              message: event.message,
              capability,
            });
            break;
          case "context-restored":
            store.getState().beginSpecimen(specimenRef.current.id);
            break;
          case "auto-rotate-changed":
            store.getState().setAutoRotate(event.enabled);
            break;
          default:
            break;
        }
      };

      let controller: ViewerController;
      try {
        controller = new ViewerController({
          container,
          onEvent: handleEvent,
          reduceMotion: reduceMotionRef.current,
          autoRotate: store.getState().autoRotate,
          initialView: store.getState().view,
        });
      } catch (cause) {
        const message =
          cause instanceof ViewerCreationError
            ? cause.message
            : `3D viewing could not start: ${cause instanceof Error ? cause.message : String(cause)}`;
        store.getState().markUnavailable("renderer-failed", message);
        callbacksRef.current.onUnavailable?.({
          reason: "renderer-failed",
          message,
          capability,
        });
        return;
      }

      controllerRef.current = controller;
      const initialSpecimen = specimenRef.current;
      store.getState().beginSpecimen(initialSpecimen.id);
      controller.setView(store.getState().view);
      controller.setCutaway(store.getState().cutaway);
      controller.setAutoRotate(store.getState().autoRotate);
      controller.focusStructure(store.getState().focusedStructureId);
      loadedRef.current = initialSpecimen.id;
      void controller.setSpecimen(initialSpecimen, assetRef.current);

      const unsubscribe = store.subscribe((state, previous) => {
        const viewer = controllerRef.current;
        if (!viewer) return;
        if (state.resetNonce !== previous.resetNonce) viewer.resetCamera();
        if (state.focusedStructureId !== previous.focusedStructureId) {
          viewer.focusStructure(state.focusedStructureId);
        }
        if (state.view !== previous.view) viewer.setView(state.view);
        if (state.cutaway !== previous.cutaway) viewer.setCutaway(state.cutaway);
        if (state.autoRotate !== previous.autoRotate) viewer.setAutoRotate(state.autoRotate);
      });

      return () => {
        unsubscribe();
        controller.dispose();
        controllerRef.current = null;
      };
    }, [store]);

    useEffect(() => {
      const controller = controllerRef.current;
      if (!controller) return;
      if (loadedRef.current === specimen.id) return;
      loadedRef.current = specimen.id;
      store.getState().beginSpecimen(specimen.id);
      controller.focusStructure(null);
      void controller.setSpecimen(specimen, asset);
    }, [specimen, asset, store]);

    useEffect(() => {
      controllerRef.current?.setReduceMotion(reduceMotion);
    }, [reduceMotion]);

    useImperativeHandle(
      ref,
      () => ({
        async screenshot() {
          const controller = controllerRef.current;
          if (!controller) throw new Error("The 3D viewer is not available");
          return controller.captureScreenshot();
        },
        async exportGlb() {
          const controller = controllerRef.current;
          if (!controller) throw new Error("The 3D viewer is not available");
          return controller.exportGlb();
        },
        reload() {
          const controller = controllerRef.current;
          if (!controller) return;
          const current = specimenRef.current;
          store.getState().beginSpecimen(current.id);
          void controller.setSpecimen(current, assetRef.current);
        },
        resetCamera() {
          controllerRef.current?.resetCamera();
        },
        focusStructure(structureId) {
          controllerRef.current?.focusStructure(structureId);
        },
      }),
      [store],
    );

    return (
      <div
        ref={containerRef}
        className={className ?? "viewer-host"}
        data-viewer-host=""
        aria-hidden="true"
      />
    );
  }),
);
