import type { Vec3 } from "./schema";

/**
 * Pure parametric anatomy evaluators for the human brain specimens.
 * Zero external dependencies so @cas/content-registry stays dependency-clean
 * while viewer-core (3D meshes) and asset-pipeline (SVG previews) share the
 * exact same coordinate space and boundary curves.
 */

export const BRAIN_LOBE_REGIONS = [
  "frontal",
  "motor",
  "sensory",
  "parietal",
  "temporal",
  "occipital",
] as const;

export type BrainLobeRegion = (typeof BRAIN_LOBE_REGIONS)[number];

export type SweptSection = {
  point: Vec3;
  rx: number;
  ry: number;
};

type Point2 = [number, number];

export function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

export function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function quadBezier2(p0: Point2, p1: Point2, p2: Point2, t: number): Point2 {
  const mt = 1 - t;
  return [
    mt * mt * p0[0] + 2 * mt * t * p1[0] + t * t * p2[0],
    mt * mt * p0[1] + 2 * mt * t * p1[1] + t * t * p2[1],
  ];
}

function arcPoint(thetaDeg: number): Point2 {
  const rad = (thetaDeg * Math.PI) / 180;
  return [Math.cos(rad), Math.sin(rad)];
}

/** Smooth C-infinity mapping from the unit disc (px, py) to [-1, 1]^2. */
function discToSquare(px: number, py: number): Point2 {
  const px2 = px * px;
  const py2 = py * py;
  const s = 2 * Math.SQRT2;
  const u =
    0.5 * Math.sqrt(Math.max(0, 2 + px2 - py2 + s * px)) -
    0.5 * Math.sqrt(Math.max(0, 2 + px2 - py2 - s * px));
  const v =
    0.5 * Math.sqrt(Math.max(0, 2 - px2 + py2 + s * py)) -
    0.5 * Math.sqrt(Math.max(0, 2 - px2 + py2 - s * py));
  return [clamp(u, -1, 1), clamp(v, -1, 1)];
}

/**
 * Domain-warped 3D gyral/sulcal field. Zero crossings become narrow creases
 * (sulci) while broad plateaus bulge outward into rounded gyri.
 */
export function corticalFoldDisplacement(x: number, y: number, z: number, amp = 0.036): number {
  const wx = x + 0.085 * Math.sin(5.2 * y + 2.7 * z) + 0.045 * Math.cos(4.1 * z - 3.3 * x);
  const wy = y + 0.085 * Math.sin(4.8 * z + 3.1 * x) + 0.045 * Math.cos(4.5 * x - 2.9 * y);
  const wz = z + 0.085 * Math.sin(5.0 * x + 2.9 * y) + 0.045 * Math.cos(4.3 * y - 3.2 * z);

  const v1 =
    Math.sin(10.6 * wx + 6.1 * wy) * Math.cos(9.8 * wz - 5.4 * wx) +
    0.55 * Math.sin(11.4 * wy - 7.8 * wz);
  const v2 = Math.sin(17.5 * wy + 10.8 * wx) * Math.cos(16.0 * wz + 8.6 * wy);

  const sulcus1 = Math.exp(-Math.pow(v1 / 0.22, 2));
  const sulcus2 = Math.exp(-Math.pow(v2 / 0.24, 2));

  return amp * (0.32 - 1.08 * sulcus1 - 0.38 * sulcus2);
}

/**
 * Evaluates a point on the right cerebral hemisphere (x = +anterior/-posterior,
 * y = +superior/-inferior, z = +right lateral / medial near 0).
 */
export function evalBrainHemispherePoint(
  ux: number,
  uy: number,
  uz: number,
  options: { cutawayRecess?: boolean; foldAmp?: number } = {},
): Vec3 {
  const cutawayRecess = options.cutawayRecess ?? false;
  const foldAmp = options.foldAmp ?? 0.036;

  const lat = Math.max(0, uz);
  const med = Math.max(0, -uz);

  // Longitudinal AP profile with gently rounded frontal and tapered occipital poles.
  let x = ux * 0.84;
  // Lateral hemisphere width: broadest around mid-parietotemporal region, narrower anteriorly/posteriorly.
  const zWidth =
    0.61 *
    (1 - 0.16 * smoothstep(0.25, 0.96, ux) - 0.22 * smoothstep(-0.32, -0.96, ux)) *
    (1 + 0.05 * (1 - uy * uy));

  // Base vertical height.
  let y = uy * 0.5 + 0.08 * (1 - ux * ux);

  // Orbital floor under frontal lobe (raises ventral frontal region).
  const orbitalMask = smoothstep(0.18, 0.82, ux) * smoothstep(0.02, -0.76, uy);
  y += 0.12 * orbitalMask;

  // Temporal lobe downward-lateral-forward bulge.
  const tempX = Math.exp(-Math.pow((ux - 0.02) / 0.34, 2));
  const tempY = smoothstep(0.14, -0.52, uy);
  const tempLat = smoothstep(0.02, 0.45, lat);
  const tempFactor = tempX * tempY * (0.45 + 0.55 * tempLat);
  y -= 0.14 * tempFactor;
  x += 0.055 * tempFactor;

  // Posterior tentorial notch beneath occipital lobe clearing space for the cerebellum.
  const tentorialMask = smoothstep(-0.12, -0.8, ux) * smoothstep(0.12, -0.68, uy);
  y += 0.24 * tentorialMask;

  // Mediolateral coordinate: convex outer dome for uz >= 0, tight interhemispheric fissure at z = 0.004.
  let z = uz >= 0 ? 0.004 + uz * zWidth + 0.04 * tempFactor : 0.004 + uz * 0.022;

  // Carve a concave medial pocket in the cutaway hemisphere so internal structures sit cleanly inside.
  if (cutawayRecess && med > 0.01) {
    const medDepth = smoothstep(0.04, 0.52, med);
    const coreX = smoothstep(-0.62, -0.22, ux) * smoothstep(0.64, 0.24, ux);
    const coreY = smoothstep(-0.48, -0.12, uy) * smoothstep(0.56, 0.16, uy);
    z += 0.23 * medDepth * coreX * coreY;
  }

  // Gyri, sulci, and major cortical fissures on the exterior cortex.
  const foldWeight = smoothstep(-0.1, 0.16, uz);
  if (foldWeight > 0) {
    const fold = corticalFoldDisplacement(x, y, z, foldAmp);

    // Sylvian fissure (lateral sulcus) groove.
    const ySyl = -0.06 - 0.22 * x;
    const sylMask =
      Math.exp(-Math.pow((y - ySyl) / 0.05, 2)) *
      smoothstep(-0.44, -0.2, x) *
      smoothstep(0.48, 0.26, x) *
      smoothstep(0.1, 0.4, lat);

    // Central sulcus groove.
    const xCen = 0.06 - 0.26 * y;
    const cenMask =
      Math.exp(-Math.pow((x - xCen) / 0.042, 2)) *
      smoothstep(-0.08, 0.12, y) *
      smoothstep(0.06, 0.35, lat);

    const disp = foldWeight * (fold - 0.046 * sylMask - 0.032 * cenMask);
    const cx = 0;
    const cy = 0.06;
    const cz = 0.02;
    const dx = x - cx;
    const dy = y - cy;
    const dz = z - cz;
    const len = Math.hypot(dx, dy, dz) || 1;
    x += (dx / len) * disp;
    y += (dy / len) * disp;
    z += (dz / len) * disp;
  }

  return [x, y, z];
}

// Shared exact junction points and boundary curves on the unit disc nx^2 + ny^2 <= 1.
const T_MOT_FRONT = arcPoint(84);
const T_CENTRAL = arcPoint(92);
const T_SENS_BACK = arcPoint(100);
const T_PAR_OCC = arcPoint(132);
const B_TEMP_FRONT = arcPoint(-82);
const B_OCC_BOT = arcPoint(-132);

const J_TEMP_BACK: Point2 = [-0.46, 0.06];
const J_SENS_BOT: Point2 = [0.02, -0.06];
const J_CEN_BOT: Point2 = [0.14, -0.1];
const J_MOT_BOT: Point2 = [0.26, -0.14];

const S_SENS_END = 0.65;
const S_CEN_END = 0.82;

function sylvianTopCurve(s: number): Point2 {
  const x = lerp(J_TEMP_BACK[0], J_MOT_BOT[0], s);
  const y = lerp(J_TEMP_BACK[1], J_MOT_BOT[1], s) + 0.025 * Math.sin(s * Math.PI);
  return [x, y];
}

function sylvianFrontCurve(t: number): Point2 {
  // t = 0 at B_TEMP_FRONT, t = 1 at J_MOT_BOT.
  return quadBezier2(B_TEMP_FRONT, [0.42, -0.44], J_MOT_BOT, t);
}

function motFrontCurve(t: number): Point2 {
  return quadBezier2(J_MOT_BOT, [0.22, 0.42], T_MOT_FRONT, t);
}

function centralSulcusCurve(t: number): Point2 {
  return quadBezier2(J_CEN_BOT, [0.1, 0.44], T_CENTRAL, t);
}

function postcentralCurve(t: number): Point2 {
  return quadBezier2(J_SENS_BOT, [-0.03, 0.46], T_SENS_BACK, t);
}

function occParietalCurve(t: number): Point2 {
  return quadBezier2(J_TEMP_BACK, [-0.52, 0.42], T_PAR_OCC, t);
}

function occTempCurve(t: number): Point2 {
  return quadBezier2(B_OCC_BOT, [-0.58, -0.35], J_TEMP_BACK, t);
}

function coonsPatch(
  u: number,
  v: number,
  left: (t: number) => Point2,
  right: (t: number) => Point2,
  bottom: (t: number) => Point2,
  top: (t: number) => Point2,
): Point2 {
  const tu = 0.5 * (u + 1);
  const tv = 0.5 * (v + 1);
  const l = left(tv);
  const r = right(tv);
  const b = bottom(tu);
  const t = top(tu);
  const p00 = left(0);
  const p10 = right(0);
  const p01 = left(1);
  const p11 = right(1);

  const nx =
    (1 - tu) * l[0] +
    tu * r[0] +
    (1 - tv) * b[0] +
    tv * t[0] -
    ((1 - tu) * (1 - tv) * p00[0] +
      tu * (1 - tv) * p10[0] +
      (1 - tu) * tv * p01[0] +
      tu * tv * p11[0]);
  const ny =
    (1 - tu) * l[1] +
    tu * r[1] +
    (1 - tv) * b[1] +
    tv * t[1] -
    ((1 - tu) * (1 - tv) * p00[1] +
      tu * (1 - tv) * p10[1] +
      (1 - tu) * tv * p01[1] +
      tu * tv * p11[1]);
  return [nx, ny];
}

function evalRegionDisc(region: BrainLobeRegion, u: number, v: number): Point2 {
  switch (region) {
    case "frontal":
      return coonsPatch(
        u,
        v,
        motFrontCurve,
        (t) => arcPoint(lerp(-82, 30, t)),
        (t) => sylvianFrontCurve(1 - t),
        (t) => arcPoint(lerp(84, 30, t)),
      );
    case "motor":
      return coonsPatch(
        u,
        v,
        centralSulcusCurve,
        motFrontCurve,
        (t) => sylvianTopCurve(lerp(S_CEN_END, 1, t)),
        (t) => arcPoint(lerp(92, 84, t)),
      );
    case "sensory":
      return coonsPatch(
        u,
        v,
        postcentralCurve,
        centralSulcusCurve,
        (t) => sylvianTopCurve(lerp(S_SENS_END, S_CEN_END, t)),
        (t) => arcPoint(lerp(100, 92, t)),
      );
    case "parietal":
      return coonsPatch(
        u,
        v,
        occParietalCurve,
        postcentralCurve,
        (t) => sylvianTopCurve(lerp(0, S_SENS_END, t)),
        (t) => arcPoint(lerp(132, 100, t)),
      );
    case "temporal":
      return coonsPatch(
        u,
        v,
        occTempCurve,
        sylvianFrontCurve,
        (t) => arcPoint(lerp(-132, -82, t)),
        sylvianTopCurve,
      );
    case "occipital":
      return coonsPatch(
        u,
        v,
        (t) => arcPoint(lerp(-162, -198, t)),
        (t) => (t <= 0.5 ? occTempCurve(t * 2) : occParietalCurve((t - 0.5) * 2)),
        (t) => arcPoint(lerp(-162, -132, t)),
        (t) => arcPoint(lerp(162, 132, t)),
      );
  }
}

/**
 * Evaluates a point on a solid, closed cortical lobe shell from unit-sphere
 * coordinates (sx, sy, sz). Outer face (sz >= 0) aligns seamlessly across
 * adjacent lobes; inner face (sz < 0) hollows cleanly to clear internal organs.
 */
export function evalBrainLobePoint(
  region: BrainLobeRegion,
  sx: number,
  sy: number,
  sz: number,
): Vec3 {
  const [u, v] = discToSquare(sx, sy);
  let [nx, ny] = evalRegionDisc(region, u, v);
  const r2 = nx * nx + ny * ny;
  if (r2 > 1) {
    const inv = 1 / Math.sqrt(r2);
    nx *= inv;
    ny *= inv;
  }
  const nz = Math.sqrt(Math.max(0, 1 - nx * nx - ny * ny));
  const outer = evalBrainHemispherePoint(nx, ny, nz, { cutawayRecess: false, foldAmp: 0.036 });

  const internalMask = smoothstep(0.06, 0.25, nz);
  const sulcalIndent = 0.026 * internalMask;
  const zRim = Math.max(0.004, outer[2] - sulcalIndent);
  if (sz >= 0) {
    const zOut = lerp(zRim, outer[2], Math.pow(sz, 0.45));
    return [outer[0], outer[1], zOut];
  }

  // Underside / medial face (sz < 0): sweep cleanly inward across the sagittal plane while carving
  // a shallow central subcortical recess for the corpus callosum and limbic core.
  const t = Math.abs(sz);
  const mx = lerp(outer[0], 0, 0.48 * t);
  const my = lerp(outer[1], 0.04, 0.48 * t);
  const coreX = smoothstep(-0.42, -0.18, mx) * smoothstep(0.44, 0.18, mx);
  const coreY = smoothstep(-0.34, -0.14, my) * smoothstep(0.3, 0.12, my);
  const zPocket = 0.004 + 0.22 * coreX * coreY;
  const zIn = lerp(zRim, Math.max(0.004, Math.min(zRim, zPocket)), Math.pow(t, 0.55));
  return [mx, my, zIn];
}

function sphereGridBounds(
  segments: number,
  evaluator: (sx: number, sy: number, sz: number) => Vec3,
): { position: Vec3; scale: Vec3 } {
  const widthSegs = Math.max(6, Math.round(segments));
  const heightSegs = Math.max(14, Math.round(widthSegs * 0.65));
  let minX = Infinity;
  let minY = Infinity;
  let minZ = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  let maxZ = -Infinity;

  for (let iy = 0; iy <= heightSegs; iy += 1) {
    const theta = (iy / heightSegs) * Math.PI;
    const sinT = Math.sin(theta);
    const cosT = Math.cos(theta);
    for (let ix = 0; ix <= widthSegs; ix += 1) {
      const phi = (ix / widthSegs) * Math.PI * 2;
      const sx = -Math.cos(phi) * sinT;
      const sy = cosT;
      const sz = Math.sin(phi) * sinT;
      const [px, py, pz] = evaluator(sx, sy, sz);
      if (px < minX) minX = px;
      if (py < minY) minY = py;
      if (pz < minZ) minZ = pz;
      if (px > maxX) maxX = px;
      if (py > maxY) maxY = py;
      if (pz > maxZ) maxZ = pz;
    }
  }

  return {
    position: [(minX + maxX) / 2, (minY + maxY) / 2, (minZ + maxZ) / 2],
    scale: [maxX - minX, maxY - minY, maxZ - minZ],
  };
}

export function computeBrainLobeFrame(
  region: BrainLobeRegion,
  segments = 36,
): { position: Vec3; scale: Vec3 } {
  return sphereGridBounds(segments, (sx, sy, sz) => evalBrainLobePoint(region, sx, sy, sz));
}

export function computeBrainHemisphereFrame(
  cutawayRecess: boolean,
  segments = 44,
): { position: Vec3; scale: Vec3 } {
  return sphereGridBounds(segments, (sx, sy, sz) =>
    evalBrainHemispherePoint(sx, sy, sz, { cutawayRecess }),
  );
}

/** Evaluates a sculpted right cerebellar hemisphere with fine parallel folia striations. */
export function evalCerebellumPoint(ux: number, uy: number, uz: number): Vec3 {
  let x = ux * 0.5;
  let y = uy * 0.44;
  const z = uz >= 0 ? 0.02 + uz * 0.48 : 0.02 + uz * 0.14;

  // Flatten superior tentorial slope and slight anterior pontine notch.
  if (uy > 0 && ux < 0.2) {
    y -= 0.06 * smoothstep(0.1, 0.85, uy) * smoothstep(0.2, -0.6, ux);
  }
  if (ux > 0.25 && uz < 0.2) {
    x -= 0.08 * smoothstep(0.25, 0.9, ux);
  }

  // Fine parallel horizontal folia grooves across outer cerebellar surface.
  const foliaMask = smoothstep(-0.2, 0.25, uz);
  const folia = Math.sin(uy * 27 + 2.1 * Math.cos(ux * 2.8) + 0.8 * Math.sin(uz * 3));
  const groove = 0.015 * folia * foliaMask;
  const len = Math.hypot(x, y, z) || 1;
  return [x + (x / len) * groove, y + (y / len) * groove, z + (z / len) * groove];
}

/**
 * Evaluates a point on the brainstem + upper spinal cord column:
 * v in [0, 1] from spinal cord bottom -> medulla -> bulging pons -> midbrain.
 */
export function evalBrainstemPoint(u: number, v: number): Vec3 {
  const angle = u * Math.PI * 2;
  const ca = Math.cos(angle); // +1 anterior (+X), -1 posterior (-X)
  const sa = Math.sin(angle); // ±1 lateral (±Z)

  // Gently posteriorly-tilted central axis from midbrain top down to spinal cord.
  const axisX = lerp(-0.07, 0.05, v);
  const y = lerp(-0.5, 0.5, v);

  // Base radius profile along spinal cord -> medulla -> pons -> midbrain.
  let rx = 0.14;
  let rz = 0.14;

  // Slender cervical spinal cord (v < 0.28).
  const cordBlend = smoothstep(0.32, 0.14, v);
  rx = lerp(rx, 0.105, cordBlend);
  rz = lerp(rz, 0.12, cordBlend);

  // Medullary pyramids & olives (v around 0.28..0.52).
  const medMask = Math.exp(-Math.pow((v - 0.39) / 0.12, 2));
  rx += 0.03 * medMask;
  rz += 0.03 * medMask;
  const pyramidRipple = Math.max(0, ca) * (0.016 * Math.cos(2 * angle)) * medMask;

  // Prominent anterior bulbous pons (v around 0.54..0.80).
  const ponsMask = Math.exp(-Math.pow((v - 0.67) / 0.11, 2));
  const antBulge = Math.max(0, ca);
  const ponsOffsetX = 0.15 * ponsMask * Math.pow(antBulge, 0.85);
  rz += 0.105 * ponsMask;
  rx += 0.045 * ponsMask;
  const ponsStriation = 0.008 * Math.sin(v * 68) * ponsMask * antBulge;

  // Superior midbrain cerebral peduncles flare (v > 0.84).
  const midMask = smoothstep(0.8, 1.0, v);
  rx += 0.05 * midMask;
  rz += 0.06 * midMask;
  // Subtle paired posterior colliculi / anterior peduncle cleft.
  const midBilobe = 0.022 * (1 - Math.cos(2 * angle)) * midMask;

  const rX = rx + pyramidRipple + ponsStriation + midBilobe;
  const rZ = rz + midBilobe * 0.8;

  return [axisX + ponsOffsetX + ca * rX, y, sa * rZ];
}

/** C-shaped corpus callosum section: rostrum -> genu -> body -> splenium. */
export function evalCorpusCallosumSection(t: number): SweptSection {
  const angle = lerp(-0.22 * Math.PI, 1.14 * Math.PI, t);
  const x = Math.cos(angle) * 0.31 + 0.04;
  const y = Math.sin(angle) * 0.165 + 0.06;
  // Thick genu (t ~ 0.18), sleek body (t ~ 0.55), bulbous splenium (t ~ 0.96).
  const genu = 0.032 * Math.exp(-Math.pow((t - 0.18) / 0.12, 2));
  const splenium = 0.042 * Math.exp(-Math.pow((t - 0.94) / 0.1, 2));
  const rostrumTaper = lerp(0.55, 1.0, smoothstep(0, 0.14, t));
  const rx = (0.05 + genu + splenium) * rostrumTaper;
  const ry = lerp(0.145, 0.18, smoothstep(0.2, 0.95, t)) * lerp(0.7, 1.0, smoothstep(0, 0.12, t));
  return { point: [x, y, 0], rx, ry };
}

/** Sweeping slender C-arch for the cingulate gyrus or fornix. */
export function evalLimbicArchSection(t: number): SweptSection {
  const angle = lerp(-0.14 * Math.PI, 1.18 * Math.PI, t);
  const x = Math.cos(angle) * 0.36;
  const y = Math.sin(angle) * 0.25 + 0.02;
  const taper = 0.72 + 0.28 * Math.sin(t * Math.PI);
  return { point: [x, y, 0], rx: 0.055 * taper, ry: 0.068 * taper };
}

/**
 * 3D seahorse / ram's-horn hippocampus curve:
 * t = 0: thick corrugated anterior pes hippocampi in medial temporal floor;
 * t = 1: tapering posterior tail sweeping upward & medially into the fornix crus.
 */
export function evalHippocampusSection(t: number): SweptSection {
  const theta = lerp(-0.32 * Math.PI, 0.76 * Math.PI, t);
  const x = 0.02 - 0.18 * Math.sin(theta * 1.1) + 0.16 * Math.cos(t * Math.PI);
  const y = -0.14 + 0.22 * smoothstep(0.18, 1.0, t) - 0.04 * Math.sin(t * Math.PI * 1.4);
  const z = 0.055 * Math.sin(t * Math.PI * 0.92) - 0.05 * smoothstep(0.65, 1.0, t);
  // Prominent bulbous pes hippocampi head at t ~ 0.08 tapering posteriorly.
  const headBulge = 0.032 * Math.exp(-Math.pow((t - 0.1) / 0.14, 2));
  const digitation = 0.008 * Math.sin(t * 28) * smoothstep(0.45, 0.02, t);
  const r = lerp(0.062, 0.028, smoothstep(0.08, 1.0, t)) + headBulge + digitation;
  return { point: [x, y, z], rx: r * 1.12, ry: r * 0.88 };
}

/**
 * C-shaped lateral ventricle horn:
 * t = 0: anterior frontal horn; t = 0.45: body; t = 0.7: posterior atrium;
 * t = 1.0: curving inferior temporal horn dipping forward-laterally.
 */
export function evalVentricleHornSection(t: number): SweptSection {
  let x: number;
  let y: number;
  let z: number;
  if (t < 0.68) {
    const u = t / 0.68;
    const ang = lerp(0.12 * Math.PI, 1.06 * Math.PI, u);
    x = Math.cos(ang) * 0.28 - 0.01;
    y = Math.sin(ang) * 0.18 + 0.02;
    z = lerp(-0.04, 0.02, u);
  } else {
    const u = (t - 0.68) / 0.32;
    const ang = lerp(1.06 * Math.PI, 1.78 * Math.PI, u);
    x = Math.cos(ang) * 0.24 - 0.05;
    y = Math.sin(ang) * 0.17 - 0.01;
    z = lerp(0.02, 0.08, u);
  }
  const frontalBulb = 0.024 * Math.exp(-Math.pow((t - 0.08) / 0.1, 2));
  const atrium = 0.028 * Math.exp(-Math.pow((t - 0.68) / 0.1, 2));
  const tipTaper = smoothstep(0, 0.08, t) * smoothstep(1.0, 0.92, t);
  const r = (0.036 + frontalBulb + atrium) * (0.45 + 0.55 * tipTaper);
  return { point: [x, y, z], rx: r * 0.9, ry: r * 1.18 };
}
