import { Raycaster, Vector2 } from "three";
import type { Camera, Mesh } from "three";

/**
 * Mouse/touch picking with a drag threshold so orbiting never selects a
 * structure accidentally. Keyboard users select from the DOM structure list.
 */
export class PointerPicker {
  private readonly element: HTMLElement;
  private readonly camera: Camera;
  private readonly getMeshes: () => Mesh[];
  private readonly onPick: (structureId: string | null) => void;
  private readonly raycaster = new Raycaster();
  private readonly pointer = new Vector2();
  private readonly visibleCandidates: Mesh[] = [];
  private downX = 0;
  private downY = 0;
  private downTime = 0;
  private pointerDown = false;
  private lastHover = 0;
  private disposed = false;

  constructor(
    element: HTMLElement,
    camera: Camera,
    getMeshes: () => Mesh[],
    onPick: (structureId: string | null) => void,
  ) {
    this.element = element;
    this.camera = camera;
    this.getMeshes = getMeshes;
    this.onPick = onPick;
    element.addEventListener("pointerdown", this.handleDown);
    element.addEventListener("pointerup", this.handleUp);
    element.addEventListener("pointercancel", this.handleCancel);
    element.addEventListener("pointermove", this.handleMove);
    element.addEventListener("pointerleave", this.handleLeave);
  }

  private setPointer(event: PointerEvent): boolean {
    const rect = this.element.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return false;
    this.pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    this.pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    return true;
  }

  private pick(): Mesh | null {
    this.raycaster.setFromCamera(this.pointer, this.camera);
    this.visibleCandidates.length = 0;
    for (const mesh of this.getMeshes()) {
      if (mesh.visible) this.visibleCandidates.push(mesh);
    }
    const hits = this.raycaster.intersectObjects(this.visibleCandidates, false);
    for (const hit of hits) {
      const structureId = hit.object.userData.structureId;
      if (typeof structureId === "string" && structureId) return hit.object as Mesh;
    }
    return null;
  }

  private handleDown = (event: PointerEvent): void => {
    if (event.pointerType === "mouse" && event.button !== 0) return;
    if (event.pointerType === "touch" && !event.isPrimary) return;
    this.pointerDown = true;
    this.downX = event.clientX;
    this.downY = event.clientY;
    this.downTime = performance.now();
  };

  private handleCancel = (): void => {
    this.pointerDown = false;
  };

  private handleUp = (event: PointerEvent): void => {
    const wasDown = this.pointerDown;
    this.pointerDown = false;
    if (this.disposed || !wasDown) return;
    if (event.pointerType === "mouse" && event.button !== 0) return;
    if (event.pointerType === "touch" && !event.isPrimary) return;
    const moved = Math.hypot(event.clientX - this.downX, event.clientY - this.downY);
    if (moved > 8 || performance.now() - this.downTime > 700) return;
    if (!this.setPointer(event)) return;
    const hit = this.pick();
    this.onPick(hit?.userData.structureId ?? null);
  };

  private handleMove = (event: PointerEvent): void => {
    if (this.disposed) return;
    const now = performance.now();
    if (now - this.lastHover < 90) return;
    this.lastHover = now;
    if (!this.setPointer(event)) return;
    const hit = this.pick();
    this.element.style.cursor = hit ? "pointer" : "";
  };

  private handleLeave = (): void => {
    this.element.style.cursor = "";
  };

  dispose(): void {
    this.disposed = true;
    this.visibleCandidates.length = 0;
    this.element.removeEventListener("pointerdown", this.handleDown);
    this.element.removeEventListener("pointerup", this.handleUp);
    this.element.removeEventListener("pointercancel", this.handleCancel);
    this.element.removeEventListener("pointermove", this.handleMove);
    this.element.removeEventListener("pointerleave", this.handleLeave);
    this.element.style.cursor = "";
  }
}
