import type { Group, Object3D } from "three";
import type { RegistryAsset } from "./types";

/**
 * Codec and loader modules are imported only from this viewer-only file, so the
 * static app entry never pulls Three.js or decoder code.
 */
export async function parseGlb(buffer: ArrayBuffer, asset: RegistryAsset): Promise<Object3D> {
  const { GLTFLoader } = await import("three/examples/jsm/loaders/GLTFLoader.js");
  const loader = new GLTFLoader();

  const required = asset.glbAudit?.extensionsRequired ?? [];
  if (required.includes("EXT_meshopt_compression")) {
    const { MeshoptDecoder } = await import("three/examples/jsm/libs/meshopt_decoder.module.js");
    if ("ready" in MeshoptDecoder && MeshoptDecoder.ready) {
      await MeshoptDecoder.ready;
    }
    loader.setMeshoptDecoder(MeshoptDecoder as Parameters<typeof loader.setMeshoptDecoder>[0]);
  }

  const gltf = await loader.parseAsync(buffer, "");
  const scene = (gltf as { scene?: Group }).scene;
  if (!scene) throw new Error("glTF file did not contain a scene");
  return scene;
}

export async function exportSceneToGlb(root: Object3D): Promise<Blob> {
  const { GLTFExporter } = await import("three/examples/jsm/exporters/GLTFExporter.js");
  const exporter = new GLTFExporter();
  const result = await new Promise<ArrayBuffer>((resolve, reject) => {
    exporter.parse(
      root,
      (output) => {
        if (output instanceof ArrayBuffer) resolve(output);
        else reject(new Error("GLB exporter returned JSON instead of binary output"));
      },
      (cause) => reject(cause instanceof Error ? cause : new Error(String(cause))),
      { binary: true, onlyVisible: false },
    );
  });
  return new Blob([result], { type: "model/gltf-binary" });
}
