import { assets, specimens } from "./assets";
import { sources } from "./citations";
import { RegistrySchema } from "./schema";
import type { AssetRecord, Registry, Specimen, Structure } from "./schema";

/**
 * Parsed at module load. A malformed registry throws immediately rather than
 * letting the UI render unvalidated content.
 */
export const registry: Registry = RegistrySchema.parse({
  version: "0.1.0",
  specimens,
  assets,
  sources,
});

const specimenIndex = new Map(registry.specimens.map((specimen) => [specimen.id, specimen]));
const assetIndex = new Map(registry.assets.map((asset) => [asset.id, asset]));
const sourceIndex = new Map(registry.sources.map((source) => [source.id, source]));

export function getSpecimen(specimenId: string): Specimen | undefined {
  return specimenIndex.get(specimenId);
}

export function requireSpecimen(specimenId: string): Specimen {
  const specimen = specimenIndex.get(specimenId);
  if (!specimen) throw new Error(`Unknown specimen: ${specimenId}`);
  return specimen;
}

export function getAsset(assetId: string): AssetRecord | undefined {
  return assetIndex.get(assetId);
}

export function requireAsset(assetId: string): AssetRecord {
  const asset = assetIndex.get(assetId);
  if (!asset) throw new Error(`Unknown asset: ${assetId}`);
  return asset;
}

export function assetForSpecimen(specimen: Specimen): AssetRecord {
  return requireAsset(specimen.assetId);
}

export function getSource(sourceId: string): (typeof registry.sources)[number] | undefined {
  return sourceIndex.get(sourceId);
}

export function getStructure(specimen: Specimen, structureId: string): Structure | undefined {
  return specimen.structures.find((structure) => structure.id === structureId);
}

export function specimenForStructure(structureId: string): Specimen[] {
  return registry.specimens.filter((specimen) =>
    specimen.structures.some((structure) => structure.id === structureId),
  );
}

export const SPECIMEN_IDS = registry.specimens.map((specimen) => specimen.id);
export const registryVersion = registry.version;
