import {
  Box3,
  Color,
  EdgesGeometry,
  Group,
  LineSegments,
  Mesh,
  Texture,
  Vector3,
  type BufferGeometry,
} from "three";
import type { Material, Object3D } from "three";
import {
  computeNormalization,
  computeWorldBounds,
  expandProcedural,
  type AssetRecord,
  type Bounds,
  type Normalization,
  type Specimen,
} from "@cas/content-registry";
import { createGeometryCache } from "./geometry";
import { createMaterialCache } from "./materials";

export type StructureMeshMap = Map<string, Mesh[]>;

export type BuiltScene = {
  root: Group;
  model: Object3D;
  meshes: Mesh[];
  structureMeshes: StructureMeshMap;
  bounds: Bounds;
  normalization: Normalization;
  meshCount: number;
  dispose: () => void;
};

const CANONICAL_DIAMETER = 2;

export function buildProceduralScene(specimen: Specimen, asset: AssetRecord): BuiltScene {
  if (!asset.procedural) {
    throw new Error(`Asset ${asset.id} has no procedural specification`);
  }
  const instances = expandProcedural(asset.procedural);
  if (instances.length === 0) {
    throw new Error(`Asset ${asset.id} expanded to zero meshes`);
  }

  const bounds = computeWorldBounds(instances);
  const normalization = computeNormalization(bounds, asset.procedural.canonicalDiameter);
  const geometries = createGeometryCache();
  const materials = createMaterialCache();
  const edgeGeometries: EdgesGeometry[] = [];
  const edgeCache = new Map<string, EdgesGeometry>();

  const root = new Group();
  root.name = `${specimen.id}:normalized`;
  root.scale.setScalar(normalization.scale);
  root.position.set(...normalization.translation);

  const model = new Group();
  model.name = specimen.id;
  root.add(model);

  const meshes: Mesh[] = [];
  const structureMeshes: StructureMeshMap = new Map();

  for (const instance of instances) {
    const geometry = geometries.forInstance(instance);
    const material = materials.get(instance.material);
    const mesh = new Mesh(geometry, material);
    mesh.name = instance.key;
    mesh.position.set(...instance.position);
    mesh.rotation.set(...instance.rotation);
    mesh.scale.set(...instance.scale);
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    if (instance.material.opacity < 0.22) mesh.renderOrder = 2;
    else if (instance.material.opacity < 0.85) mesh.renderOrder = 1;
    else mesh.renderOrder = 0;
    mesh.userData = {
      baseMaterial: material,
      instanceKey: instance.key,
      partId: instance.partId,
      structureId: instance.structureId ?? null,
      cutawayHide: instance.cutawayHide,
    };
    model.add(mesh);
    meshes.push(mesh);

    if (instance.structureId) {
      const list = structureMeshes.get(instance.structureId) ?? [];
      list.push(mesh);
      structureMeshes.set(instance.structureId, list);
    }

    if (instance.outline) {
      let edges = edgeCache.get(geometry.uuid);
      if (!edges) {
        edges = new EdgesGeometry(geometry, 26);
        edgeCache.set(geometry.uuid, edges);
        edgeGeometries.push(edges);
      }
      const dark = instance.material.color;
      const lineColor = new Color(dark).multiplyScalar(0.62).getHexString();
      const line = new LineSegments(edges, materials.line(`#${lineColor}`, 0.3));
      line.raycast = () => {
        /* Outlines are decoration and must never intercept picking. */
      };
      line.renderOrder = 3;
      mesh.add(line);
    }
  }

  return {
    root,
    model,
    meshes,
    structureMeshes,
    bounds,
    normalization,
    meshCount: meshes.length,
    dispose: () => {
      for (const edges of edgeGeometries) edges.dispose();
      geometries.dispose();
      materials.dispose();
      root.removeFromParent();
      root.clear();
    },
  };
}

export function disposeObject3D(object: Object3D): void {
  const geometries = new Set<BufferGeometry>();
  const sceneMaterials = new Set<Material>();
  const textures = new Set<Texture>();
  object.traverse((child) => {
    if (!(child instanceof Mesh)) return;
    if (child.geometry) geometries.add(child.geometry);
    const childMaterials = Array.isArray(child.material) ? child.material : [child.material];
    for (const material of childMaterials) {
      sceneMaterials.add(material);
      for (const value of Object.values(material)) {
        if (value instanceof Texture) textures.add(value);
      }
    }
  });
  for (const geometry of geometries) geometry.dispose();
  for (const material of sceneMaterials) material.dispose();
  for (const texture of textures) texture.dispose();
}

/**
 * Wrap an already-parsed glTF scene. The offline pipeline owns normalisation
 * values for shipped GLBs; this runtime fallback only centres and scales so a
 * malformed asset cannot produce non-finite bounds.
 */
export function buildLoadedScene(
  specimen: Specimen,
  asset: AssetRecord,
  object: Object3D,
): BuiltScene {
  const box = new Box3().setFromObject(object);
  const size = box.getSize(new Vector3());
  if (!box.isEmpty() && [size.x, size.y, size.z].every((value) => Number.isFinite(value))) {
    // Use the shared normalisation math so the golden report and runtime agree.
    for (const axis of ["x", "y", "z"] as const) {
      if (!Number.isFinite(box.min[axis]) || !Number.isFinite(box.max[axis])) {
        throw new Error("Loaded scene has non-finite bounds");
      }
    }
  }
  const bounds: Bounds = {
    min: [box.min.x, box.min.y, box.min.z],
    max: [box.max.x, box.max.y, box.max.z],
  };
  const normalization = computeNormalization(bounds, CANONICAL_DIAMETER);

  const root = new Group();
  root.name = `${specimen.id}:normalized`;
  root.scale.setScalar(normalization.scale);
  root.position.set(...normalization.translation);
  root.add(object);

  const meshes: Mesh[] = [];
  const structureMeshes: StructureMeshMap = new Map();
  const namesByStructure = new Map(
    specimen.structures.map((structure) => [structure.id, new Set(structure.mapping.meshNames)]),
  );

  root.updateMatrixWorld(true);
  object.traverse((child) => {
    if (!(child instanceof Mesh)) return;
    meshes.push(child);
    child.userData.baseMaterial = child.material;

    for (const [structureId, names] of namesByStructure) {
      let cursor: Object3D | null = child;
      let matched = false;
      while (cursor) {
        if (names.has(cursor.name)) {
          matched = true;
          break;
        }
        cursor = cursor.parent;
      }
      if (matched) {
        if (!child.userData.structureId) child.userData.structureId = structureId;
        const list = structureMeshes.get(structureId) ?? [];
        list.push(child);
        structureMeshes.set(structureId, list);
      }
    }
  });

  if (meshes.length === 0) {
    throw new Error(`Asset ${asset.id} contains no meshes`);
  }

  return {
    root,
    model: object,
    meshes,
    structureMeshes,
    bounds,
    normalization,
    meshCount: meshes.length,
    dispose: () => {
      root.removeFromParent();
      disposeObject3D(object);
      root.clear();
    },
  };
}
