import type { ViewerUnavailableReason } from "./events";

export type LoadStatus = "idle" | "loading" | "ready" | "error";

export type LoadError = {
  code: ViewerUnavailableReason;
  message: string;
  retryable: boolean;
};

export type LoadState = {
  status: LoadStatus;
  specimenId: string | null;
  /** The last successfully rendered specimen, kept on screen while a new one loads. */
  visibleSpecimenId: string | null;
  progress: number;
  error: LoadError | null;
};

export type LoadAction =
  | { type: "start"; specimenId: string }
  | { type: "progress"; specimenId: string; progress: number }
  | { type: "success"; specimenId: string }
  | { type: "failure"; specimenId: string; error: LoadError }
  | { type: "cancel"; specimenId: string }
  | { type: "eject" };

export const initialLoadState: LoadState = {
  status: "idle",
  specimenId: null,
  visibleSpecimenId: null,
  progress: 0,
  error: null,
};

/**
 * Pure loading/failure reducer. Explicit states (instead of boolean flags) make
 * the "keep the previous model while the next one loads" rule testable.
 */
export function reduceLoadState(state: LoadState, action: LoadAction): LoadState {
  switch (action.type) {
    case "start": {
      return {
        ...state,
        status: "loading",
        specimenId: action.specimenId,
        progress: 0,
        error: null,
      };
    }
    case "progress": {
      if (state.status !== "loading" || state.specimenId !== action.specimenId) return state;
      const progress = Math.max(0, Math.min(1, action.progress));
      if (progress <= state.progress) return state;
      return { ...state, progress };
    }
    case "success": {
      if (state.specimenId !== action.specimenId) return state;
      return {
        ...state,
        status: "ready",
        visibleSpecimenId: action.specimenId,
        progress: 1,
        error: null,
      };
    }
    case "failure": {
      if (state.specimenId !== action.specimenId) return state;
      return {
        ...state,
        status: "error",
        error: action.error,
      };
    }
    case "cancel": {
      if (state.status !== "loading" || state.specimenId !== action.specimenId) return state;
      return {
        ...state,
        status: state.visibleSpecimenId ? "ready" : "idle",
        specimenId: state.visibleSpecimenId,
        progress: 0,
        error: null,
      };
    }
    case "eject": {
      return initialLoadState;
    }
    default: {
      return state;
    }
  }
}

export function isStaleLoad(state: LoadState, specimenId: string): boolean {
  return state.status === "loading" && state.specimenId !== specimenId;
}
