import { alignYToVector, limbBetween, mat, part } from "../authoring";
import type { ProceduralSpec, Vec3 } from "../schema";

export function buildParameciumProcedural(): ProceduralSpec {
  // Generate 60 cilia arranged along four longitudinal kineties around the slipper hull.
  const CILIA_SITES: Array<{ position: Vec3; rotation: Vec3; scale: Vec3 }> = [];
  const CILIA_ROWS = 4;
  const CILIA_PER_ROW = 15;
  for (let row = 0; row < CILIA_ROWS; row += 1) {
    const phi = (row / CILIA_ROWS) * Math.PI * 2 + 0.38;
    for (let col = 0; col < CILIA_PER_ROW; col += 1) {
      const u = -0.82 + (col / (CILIA_PER_ROW - 1)) * 1.64; // Normalized X parameter along body.
      const radialFactor = Math.sqrt(Math.max(0.08, 1 - u * u));
      const taper = 1 - 0.14 * Math.max(0, u);
      const sx = u * 1.02;
      const sy = Math.cos(phi) * radialFactor * taper * 0.45;
      const sz = Math.sin(phi) * radialFactor * taper * 0.41;
      // Outward ellipsoid normal + slight posterior stroke tilt (+0.32 in X).
      const nx = u * 0.44 + 0.34;
      const ny = Math.cos(phi) * radialFactor * taper * 1.02;
      const nz = Math.sin(phi) * radialFactor * taper * 1.1;
      const tip: Vec3 = [sx + nx * 0.11, sy + ny * 0.11, sz + nz * 0.11];
      const seg = limbBetween([sx, sy, sz], tip, 0.015, 1);
      CILIA_SITES.push(seg);
    }
  }

  const ORAL_CILIA: Array<{ position: Vec3; rotation: Vec3; scale: Vec3 }> = Array.from(
    { length: 6 },
    (_, idx) => {
      const t = idx / 5;
      const base: Vec3 = [-0.62 + t * 0.56, -0.14 - t * 0.04, 0.38 - t * 0.06];
      const tip: Vec3 = [base[0] + 0.04, base[1] - 0.03, base[2] + 0.09];
      return limbBetween(base, tip, 0.016, 1);
    },
  );

  const VACUOLE_CENTERS: Vec3[] = [
    [-0.56, 0.14, -0.02],
    [0.58, 0.12, -0.02],
  ];

  const VACUOLE_CANALS = VACUOLE_CENTERS.flatMap((center, vIdx) =>
    Array.from({ length: 6 }, (_, rayIdx) => {
      const angle = (rayIdx / 6) * Math.PI * 2 + (vIdx === 0 ? 0.25 : -0.25);
      const tip: Vec3 = [
        center[0] + Math.cos(angle) * 0.24,
        center[1] + Math.sin(angle) * 0.17,
        center[2] + Math.sin(angle * 2) * 0.07,
      ];
      return {
        key: `cv-canal-${vIdx}-${rayIdx}`,
        seg: limbBetween(center, tip, 0.056, 1),
      };
    }),
  );

  const FOOD_VACUOLES: Array<{ pos: Vec3; scale: number }> = [
    { pos: [0.18, -0.18, 0.14], scale: 0.12 },
    { pos: [0.36, -0.12, -0.08], scale: 0.11 },
    { pos: [0.34, 0.1, -0.18], scale: 0.1 },
    { pos: [-0.26, -0.16, -0.18], scale: 0.11 },
    { pos: [-0.42, -0.08, 0.14], scale: 0.1 },
    { pos: [-0.14, 0.22, 0.16], scale: 0.095 },
  ];

  const CILIA_MAT = mat("#b4ebe3", {
    roughness: 0.38,
    clearcoat: 0.32,
    emissive: "#2b7369",
    emissiveIntensity: 0.1,
  });
  const CV_MAT = mat("#70ccfa", {
    opacity: 0.65,
    roughness: 0.2,
    clearcoat: 0.8,
    emissive: "#1a689c",
    emissiveIntensity: 0.2,
  });
  const FV_SHELL_MAT = mat("#c7a95f", {
    opacity: 0.44,
    roughness: 0.28,
    clearcoat: 0.65,
    emissive: "#694d14",
    emissiveIntensity: 0.14,
  });
  const FV_PELLET_MAT = mat("#7aa859", {
    roughness: 0.5,
    emissive: "#2e541c",
    emissiveIntensity: 0.18,
  });

  return {
    units: "schematic",
    canonicalDiameter: 2,
    notes:
      "Schematic ciliate protist (Paramecium caudatum). A sculpted slipper-shaped pellicle (with authored cutaway) carries four longitudinal rows of tapered cilia, an indented anterior oral groove leading to the cytostome, a kidney-shaped polyploid macronucleus paired with a small micronucleus, two star-shaped contractile vacuoles with radiating canals, and cycling food vacuoles.",
    parts: [
      part({
        id: "pellicle-body",
        shape: "organicBlob",
        position: [0, 0, 0],
        scale: [2.08, 0.92, 0.84],
        material: mat("#6cc9bf", {
          opacity: 0.16,
          roughness: 0.22,
          clearcoat: 0.82,
          emissive: "#1b5e57",
          emissiveIntensity: 0.08,
        }),
        structureId: "pellicle",
        cutawayHide: true,
        outline: true,
        segments: 44,
      }),
      part({
        id: "pellicle-posterior",
        shape: "taperedBranch",
        position: [0.82, -0.02, 0],
        rotation: [0, 0, -Math.PI / 2],
        scale: [0.58, 0.56, 0.54],
        material: mat("#6cc9bf", {
          opacity: 0.15,
          roughness: 0.24,
          clearcoat: 0.78,
          emissive: "#1b5e57",
          emissiveIntensity: 0.08,
        }),
        structureId: "pellicle",
        cutawayHide: true,
        segments: 24,
      }),
      ...CILIA_SITES.map((seg, idx) =>
        part({
          id: `cilium-${idx}`,
          shape: "taperedBranch",
          position: seg.position,
          rotation: seg.rotation,
          scale: seg.scale,
          material: CILIA_MAT,
          structureId: "cilia",
          segments: 8,
        }),
      ),
      part({
        id: "oral-groove-channel",
        shape: "curvedSheet",
        position: [-0.32, -0.1, 0.24],
        rotation: [0.35, -0.42, -0.22],
        scale: [0.56, 0.14, 0.24],
        material: mat("#4ea69d", {
          opacity: 0.48,
          roughness: 0.3,
          clearcoat: 0.55,
          emissive: "#164f49",
          emissiveIntensity: 0.14,
        }),
        structureId: "oral-groove",
        segments: 20,
      }),
      part({
        id: "oral-cytostome",
        shape: "torus",
        position: [0.02, -0.17, 0.25],
        rotation: alignYToVector([-0.3, -0.2, 0.93]),
        scale: [0.22, 0.22, 0.34],
        material: mat("#8ee0d4", {
          roughness: 0.3,
          clearcoat: 0.55,
          emissive: "#236e63",
          emissiveIntensity: 0.2,
        }),
        structureId: "oral-groove",
        segments: 20,
      }),
      part({
        id: "oral-cytopharynx",
        shape: "taperedBranch",
        position: [0.09, -0.17, 0.18],
        rotation: alignYToVector([0.7, 0.05, -0.7]),
        scale: [0.1, 0.22, 0.1],
        material: mat("#5db8ad", { opacity: 0.72, roughness: 0.35 }),
        structureId: "oral-groove",
        segments: 14,
      }),
      ...ORAL_CILIA.map((seg, idx) =>
        part({
          id: `oral-cilium-${idx}`,
          shape: "taperedBranch",
          position: seg.position,
          rotation: seg.rotation,
          scale: seg.scale,
          material: mat("#c8f5ee", {
            roughness: 0.35,
            emissive: "#35786e",
            emissiveIntensity: 0.12,
          }),
          structureId: "oral-groove",
          segments: 8,
        }),
      ),
      part({
        id: "macronucleus-anterior",
        shape: "organicBlob",
        position: [-0.07, 0.09, -0.03],
        rotation: [0.1, 0.2, 0.42],
        scale: [0.34, 0.24, 0.23],
        material: mat("#8270d4", {
          opacity: 0.72,
          roughness: 0.34,
          clearcoat: 0.5,
          emissive: "#352670",
          emissiveIntensity: 0.16,
        }),
        structureId: "macronucleus",
        segments: 26,
      }),
      part({
        id: "macronucleus-posterior",
        shape: "organicBlob",
        position: [0.14, 0.07, -0.04],
        rotation: [-0.1, -0.2, -0.45],
        scale: [0.32, 0.23, 0.22],
        material: mat("#8270d4", {
          opacity: 0.72,
          roughness: 0.34,
          clearcoat: 0.5,
          emissive: "#352670",
          emissiveIntensity: 0.16,
        }),
        structureId: "macronucleus",
        segments: 26,
      }),
      part({
        id: "macronucleus-chromatin",
        shape: "torusKnot",
        position: [0.03, 0.09, -0.03],
        scale: [0.28, 0.14, 0.14],
        material: mat("#a596eb", { roughness: 0.48, emissive: "#493796", emissiveIntensity: 0.18 }),
        structureId: "macronucleus",
        segments: 24,
      }),
      part({
        id: "micronucleus",
        shape: "sphere",
        position: [0.02, -0.04, 0.06],
        scale: [0.135, 0.135, 0.135],
        material: mat("#d1a8ff", {
          roughness: 0.3,
          clearcoat: 0.65,
          emissive: "#6b38b5",
          emissiveIntensity: 0.26,
        }),
        structureId: "micronucleus",
        segments: 20,
      }),
      ...VACUOLE_CENTERS.map((center, vIdx) =>
        part({
          id: `cv-bladder-${vIdx}`,
          shape: "sphere",
          position: center,
          scale: [0.16, 0.15, 0.15],
          material: CV_MAT,
          structureId: "contractile-vacuole",
          segments: 20,
        }),
      ),
      ...VACUOLE_CANALS.map(({ key, seg }) =>
        part({
          id: key,
          shape: "taperedBranch",
          position: seg.position,
          rotation: seg.rotation,
          scale: seg.scale,
          material: CV_MAT,
          structureId: "contractile-vacuole",
          segments: 12,
        }),
      ),
      ...FOOD_VACUOLES.flatMap((fv, idx) => [
        part({
          id: `food-vacuole-${idx}`,
          shape: "sphere",
          position: fv.pos,
          scale: [fv.scale, fv.scale, fv.scale],
          material: FV_SHELL_MAT,
          structureId: "food-vacuole",
          segments: 16,
        }),
        part({
          id: `food-vacuole-content-${idx}`,
          shape: "sphere",
          position: fv.pos,
          scale: [fv.scale * 0.52, fv.scale * 0.52, fv.scale * 0.52],
          material: FV_PELLET_MAT,
          structureId: "food-vacuole",
          segments: 10,
        }),
      ]),
    ],
  };
}

export const parameciumProcedural: ProceduralSpec = /*#__PURE__*/ buildParameciumProcedural();
