import type { ViewerUnavailableReason } from "./events";

export type AssetErrorCode = Extract<
  ViewerUnavailableReason,
  | "asset-missing"
  | "asset-timeout"
  | "asset-http"
  | "asset-corrupt"
  | "asset-decode"
  | "cancelled"
  | "unknown"
>;

export class AssetLoadError extends Error {
  readonly code: AssetErrorCode;
  readonly retryable: boolean;
  readonly status: number | null;

  constructor(
    code: AssetErrorCode,
    message: string,
    options: { retryable?: boolean; status?: number } = {},
  ) {
    super(message);
    this.name = "AssetLoadError";
    this.code = code;
    this.retryable = options.retryable ?? false;
    this.status = options.status ?? null;
  }
}

export type LoadGlbOptions = {
  signal?: AbortSignal;
  timeoutMs?: number;
  /** Additional attempts for transient network/5xx/timeout failures. */
  retries?: number;
  fetchImpl?: typeof fetch;
  onProgress?: (progress: number) => void;
  maxBytes?: number;
};

/** 32 MiB runtime safety cap — above the per-asset 8 MiB release budget. */
const RUNTIME_MAX_BYTES = 32 * 1024 * 1024;
const DEFAULT_TIMEOUT_MS = 20_000;

function delay(ms: number, signal?: AbortSignal): Promise<void> {
  if (signal?.aborted) {
    return Promise.reject(new AssetLoadError("cancelled", "Asset loading was cancelled"));
  }
  return new Promise((resolve, reject) => {
    const onAbort = () => {
      clearTimeout(timer);
      reject(new AssetLoadError("cancelled", "Asset loading was cancelled"));
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

/**
 * Fetch and decode a GLB with bounded retries, cancellation, and progress.
 * Decoding is injected so the failure machine can be tested without a DOM.
 */
export async function loadGlbAsset<T>(
  url: string,
  parse: (buffer: ArrayBuffer) => Promise<T>,
  options: LoadGlbOptions = {},
): Promise<T> {
  if (!url) {
    throw new AssetLoadError("asset-missing", "No asset URL was provided");
  }
  const retries = options.retries ?? 1;
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const fetchImpl = options.fetchImpl ?? fetch;
  const maxBytes = options.maxBytes ?? RUNTIME_MAX_BYTES;

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    try {
      const buffer = await fetchBytes(url, fetchImpl, options, timeoutMs, maxBytes);
      try {
        return await parse(buffer);
      } catch (cause) {
        throw new AssetLoadError(
          "asset-corrupt",
          `Model could not be decoded: ${cause instanceof Error ? cause.message : String(cause)}`,
        );
      }
    } catch (cause) {
      const error =
        cause instanceof AssetLoadError
          ? cause
          : new AssetLoadError("unknown", cause instanceof Error ? cause.message : String(cause));
      if (error.code === "cancelled") throw error;
      if (!error.retryable || attempt >= retries) throw error;
      await delay(250 * (attempt + 1), options.signal);
    }
  }

  throw new AssetLoadError("unknown", "Asset loading failed after retries");
}

async function fetchBytes(
  url: string,
  fetchImpl: typeof fetch,
  options: LoadGlbOptions,
  timeoutMs: number,
  maxBytes: number,
): Promise<ArrayBuffer> {
  const controller = new AbortController();
  let timedOut = false;
  const timeout = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, timeoutMs);

  const onOuterAbort = () => controller.abort();
  if (options.signal) {
    if (options.signal.aborted) {
      clearTimeout(timeout);
      throw new AssetLoadError("cancelled", "Asset loading was cancelled");
    }
    options.signal.addEventListener("abort", onOuterAbort, { once: true });
  }

  const cleanup = () => {
    clearTimeout(timeout);
    options.signal?.removeEventListener("abort", onOuterAbort);
  };

  try {
    const response = await fetchImpl(url, {
      signal: controller.signal,
      headers: { Accept: "model/gltf-binary" },
      credentials: "same-origin",
    });

    if (!response.ok) {
      const retryable =
        response.status >= 500 || response.status === 408 || response.status === 429;
      const code = response.status === 404 ? "asset-missing" : "asset-http";
      throw new AssetLoadError(
        code,
        response.status === 404
          ? `Model file was not found (${url})`
          : `Model request failed with HTTP ${response.status}`,
        { retryable, status: response.status },
      );
    }

    const declaredLength = Number(response.headers.get("content-length") ?? "0");
    if (declaredLength > maxBytes) {
      throw new AssetLoadError("asset-corrupt", "Model exceeds the runtime size limit");
    }

    const buffer = await readResponseBytes(response, declaredLength, maxBytes, options.onProgress);
    return buffer;
  } catch (cause) {
    cleanup();
    if (cause instanceof AssetLoadError) throw cause;
    if (options.signal?.aborted) {
      throw new AssetLoadError("cancelled", "Asset loading was cancelled");
    }
    if (timedOut) {
      throw new AssetLoadError("asset-timeout", "Model loading timed out", { retryable: true });
    }
    throw new AssetLoadError(
      "asset-http",
      cause instanceof Error ? cause.message : "Network request failed",
      { retryable: true },
    );
  } finally {
    cleanup();
  }
}

async function readResponseBytes(
  response: Response,
  declaredLength: number,
  maxBytes: number,
  onProgress: ((progress: number) => void) | undefined,
): Promise<ArrayBuffer> {
  if (!response.body) {
    const buffer = await response.arrayBuffer();
    if (buffer.byteLength > maxBytes) {
      throw new AssetLoadError("asset-corrupt", "Model exceeds the runtime size limit");
    }
    onProgress?.(1);
    return buffer;
  }

  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let received = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    if (value) {
      received += value.byteLength;
      if (received > maxBytes) {
        await reader.cancel();
        throw new AssetLoadError("asset-corrupt", "Model exceeds the runtime size limit");
      }
      chunks.push(value);
      if (declaredLength > 0) {
        onProgress?.(Math.min(0.95, received / declaredLength));
      }
    }
  }

  const output = new Uint8Array(received);
  let offset = 0;
  for (const chunk of chunks) {
    output.set(chunk, offset);
    offset += chunk.byteLength;
  }
  onProgress?.(1);
  return output.buffer;
}
