import { MathUtils, Vector3 } from "three";
import type { Box3, PerspectiveCamera } from "three";
import type { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";

const HOME_DIRECTION = new Vector3(0.46, 0.34, 0.86).normalize();

/**
 * Owns camera transitions. Pointer-driven orbiting stays inside OrbitControls;
 * this class only handles deliberate framing/reset animation, so no frame-rate
 * transform ever enters React or the stores.
 */
export class CameraDirector {
  private readonly camera: PerspectiveCamera;
  private readonly controls: OrbitControls;
  private homePosition = new Vector3(2.1, 1.55, 3.2);
  private homeTarget = new Vector3(0, 0, 0);
  private desiredPosition = new Vector3();
  private desiredTarget = new Vector3();
  private animating = false;
  private reduceMotion = false;

  constructor(camera: PerspectiveCamera, controls: OrbitControls) {
    this.camera = camera;
    this.controls = controls;
  }

  setHome(radius: number, center: Vector3 = new Vector3(0, 0, 0)): void {
    const fov = MathUtils.degToRad(this.camera.fov);
    const distance = MathUtils.clamp((radius / Math.tan(fov / 2)) * 1.18, 2.1, 6.5);
    this.homeTarget.copy(center);
    this.homePosition.copy(center).addScaledVector(HOME_DIRECTION, distance);
  }

  setReduceMotion(reduceMotion: boolean): void {
    this.reduceMotion = reduceMotion;
  }

  reset(): void {
    this.desiredPosition.copy(this.homePosition);
    this.desiredTarget.copy(this.homeTarget);
    this.animating = true;
    if (this.reduceMotion) this.snap();
  }

  frame(box: Box3 | null): void {
    if (!box || box.isEmpty()) {
      this.reset();
      return;
    }
    const center = box.getCenter(new Vector3());
    const size = box.getSize(new Vector3());
    const radius = Math.max(size.length() / 2, 0.16);
    const fov = MathUtils.degToRad(this.camera.fov);
    const distance = MathUtils.clamp((radius / Math.sin(fov / 2)) * 1.45, 1.15, 7);

    const direction = this.camera.position.clone().sub(this.controls.target);
    if (direction.lengthSq() < 1e-6) direction.copy(HOME_DIRECTION);
    direction.normalize();

    this.desiredTarget.copy(center);
    this.desiredPosition.copy(center).addScaledVector(direction, distance);
    this.animating = true;
    if (this.reduceMotion) this.snap();
  }

  cancel(): void {
    this.animating = false;
  }

  isAnimating(): boolean {
    return this.animating;
  }

  update(deltaSeconds: number): boolean {
    if (!this.animating) return false;
    const alpha = this.reduceMotion ? 1 : 1 - Math.exp(-Math.min(deltaSeconds, 0.05) * 10);
    this.camera.position.lerp(this.desiredPosition, alpha);
    this.controls.target.lerp(this.desiredTarget, alpha);

    const closeEnough =
      this.camera.position.distanceToSquared(this.desiredPosition) < 1e-6 &&
      this.controls.target.distanceToSquared(this.desiredTarget) < 1e-6;
    if (closeEnough) this.snap();
    return true;
  }

  snap(): void {
    this.camera.position.copy(this.desiredPosition);
    this.controls.target.copy(this.desiredTarget);
    this.controls.update();
    this.animating = false;
  }
}
